// PlanGalopStats counts one parse's work: Passes is how many times it parsed from
// the first token (1 when the first pass succeeds), Predictions its runtime
// (adaptive) predictions and FullContext its full-context ones. Plain fields
// of the parser, so counting costs no synchronization.
type PlanGalopStats struct {
	Passes, Predictions, FullContext int
}

// PlanGalopEmptyReturn is the return state that marks the end of the outermost context.
const PlanGalopEmptyReturn = int32(0x7fffffff)

// PlanGalopCtxPool holds hash-consed prediction contexts. Context 0 is EMPTY; every
// other context is a singleton (one return state and parent) or an array
// (return states in ascending order, with parents). A parent of -1 is nil.
type PlanGalopCtxPool struct {
	wildcard bool
	kind     []uint8
	start    []int32
	length   []int32
	rets     []int32
	parents  []int32
	next     []int32
	heads    PlanGalopMap
	singles  PlanGalopMap
	merges   PlanGalopMap
}

const (
	PlanGalopCtxEmpty     = 0
	PlanGalopCtxSingleton = 1
	PlanGalopCtxArray     = 2
)

func (cp *PlanGalopCtxPool) reset(wildcard bool) {
	cp.wildcard = wildcard
	cp.kind = append(cp.kind[:0], PlanGalopCtxEmpty)
	cp.start = append(cp.start[:0], 0)
	cp.length = append(cp.length[:0], 1)
	cp.rets = append(cp.rets[:0], PlanGalopEmptyReturn)
	cp.parents = append(cp.parents[:0], -1)
	cp.next = append(cp.next[:0], -1)
	cp.heads.reset()
	cp.singles.reset()
	cp.merges.reset()
}

// intern returns the id of the context (kind, rets, parents), adding it if new.
// Contexts are found through a hash of their contents and a chain of the ids
// that share it. Singletons are interned by singleton instead.
func (cp *PlanGalopCtxPool) intern(kind uint8, rets, parents []int32) int32 {
	h := uint64(kind) + 0x9e3779b97f4a7c15
	for i := range rets {
		h = PlanGalopMix(h ^ (uint64(uint32(rets[i]))<<32 | uint64(uint32(parents[i]))))
	}
	head, found := cp.heads.get(h)
	if found {
		for id := head; id >= 0; id = cp.next[id] {
			if cp.kind[id] != kind || int(cp.length[id]) != len(rets) {
				continue
			}
			s, same := cp.start[id], true
			for i := range rets {
				if cp.rets[s+int32(i)] != rets[i] || cp.parents[s+int32(i)] != parents[i] {
					same = false
					break
				}
			}
			if same {
				return id
			}
		}
	} else {
		head = -1
	}
	id := int32(len(cp.kind))
	cp.kind = append(cp.kind, kind)
	cp.start = append(cp.start, int32(len(cp.rets)))
	cp.length = append(cp.length, int32(len(rets)))
	cp.rets = append(cp.rets, rets...)
	cp.parents = append(cp.parents, parents...)
	cp.next = append(cp.next, head)
	cp.heads.set(h, id)
	return id
}

// singleton is ANTLR's SingletonBasePredictionContextCreate. Closure creates
// one at every rule call, so singletons skip the hash chains of intern: their
// return state and parent are the whole key.
func (cp *PlanGalopCtxPool) singleton(parent, ret int32) int32 {
	if ret == PlanGalopEmptyReturn && parent < 0 {
		return 0
	}
	k := uint64(uint32(ret))<<32 | uint64(uint32(parent))
	if id, ok := cp.singles.get(k); ok {
		return id
	}
	id := int32(len(cp.kind))
	cp.kind = append(cp.kind, PlanGalopCtxSingleton)
	cp.start = append(cp.start, int32(len(cp.rets)))
	cp.length = append(cp.length, 1)
	cp.rets = append(cp.rets, ret)
	cp.parents = append(cp.parents, parent)
	cp.next = append(cp.next, -1)
	cp.singles.set(k, id)
	return id
}

func (cp *PlanGalopCtxPool) isEmpty(c int32) bool {
	switch cp.kind[c] {
	case PlanGalopCtxEmpty:
		return true
	case PlanGalopCtxArray:
		return cp.length[c] > 0 && cp.rets[cp.start[c]] == PlanGalopEmptyReturn
	}
	return false
}

// toArray is ANTLR's convertToArray: EMPTY becomes an array with no entries.
func (cp *PlanGalopCtxPool) toArray(c int32) int32 {
	switch cp.kind[c] {
	case PlanGalopCtxEmpty:
		return cp.intern(PlanGalopCtxArray, nil, nil)
	case PlanGalopCtxSingleton:
		s := cp.start[c]
		one := [2]int32{cp.rets[s], cp.parents[s]}
		return cp.intern(PlanGalopCtxArray, one[0:1], one[1:2])
	}
	return c
}

func PlanGalopMergeKey(a, b int32) uint64 { return uint64(uint32(a))<<32 | uint64(uint32(b)) }

func (cp *PlanGalopCtxPool) cached(a, b int32) (int32, bool) {
	if r, ok := cp.merges.get(PlanGalopMergeKey(a, b)); ok {
		return r, true
	}
	return cp.merges.get(PlanGalopMergeKey(b, a))
}

// merge is ANTLR's merge(a, b, rootIsWildcard, mergeCache).
func (cp *PlanGalopCtxPool) merge(a, b int32) int32 {
	if a == b {
		return a
	}
	if cp.kind[a] == PlanGalopCtxSingleton && cp.kind[b] == PlanGalopCtxSingleton {
		return cp.mergeSingletons(a, b)
	}
	if cp.wildcard {
		if cp.isEmpty(a) {
			return a
		}
		if cp.isEmpty(b) {
			return b
		}
	}
	return cp.mergeArrays(cp.toArray(a), cp.toArray(b))
}

func (cp *PlanGalopCtxPool) mergeSingletons(a, b int32) int32 {
	if r, ok := cp.cached(a, b); ok {
		return r
	}
	ar, ap := cp.rets[cp.start[a]], cp.parents[cp.start[a]]
	br, bp := cp.rets[cp.start[b]], cp.parents[cp.start[b]]
	var r int32
	if ar == br {
		parent := cp.merge(ap, bp)
		if parent == ap {
			return a
		}
		if parent == bp {
			return b
		}
		r = cp.singleton(parent, ar)
	} else if ap >= 0 && ap == bp {
		lo, hi := min(ar, br), max(ar, br)
		r = cp.intern(PlanGalopCtxArray, []int32{lo, hi}, []int32{ap, ap})
	} else if ar < br {
		r = cp.intern(PlanGalopCtxArray, []int32{ar, br}, []int32{ap, bp})
	} else {
		r = cp.intern(PlanGalopCtxArray, []int32{br, ar}, []int32{bp, ap})
	}
	cp.merges.set(PlanGalopMergeKey(a, b), r)
	return r
}

func (cp *PlanGalopCtxPool) mergeArrays(a, b int32) int32 {
	if r, ok := cp.cached(a, b); ok {
		return r
	}
	as, al := cp.start[a], cp.length[a]
	bs, bl := cp.start[b], cp.length[b]
	rets := make([]int32, 0, al+bl)
	parents := make([]int32, 0, al+bl)
	i, j := int32(0), int32(0)
	for i < al && j < bl {
		ar, ap := cp.rets[as+i], cp.parents[as+i]
		br, bp := cp.rets[bs+j], cp.parents[bs+j]
		switch {
		case ar == br:
			bothDollars := ar == PlanGalopEmptyReturn && ap < 0 && bp < 0
			if bothDollars || (ap >= 0 && bp >= 0 && ap == bp) {
				parents = append(parents, ap)
			} else {
				parents = append(parents, cp.merge(ap, bp))
				// The merge may have grown the pool; re-read the bases.
				as, bs = cp.start[a], cp.start[b]
			}
			rets = append(rets, ar)
			i++
			j++
		case ar < br:
			rets, parents = append(rets, ar), append(parents, ap)
			i++
		default:
			rets, parents = append(rets, br), append(parents, bp)
			j++
		}
	}
	for ; i < al; i++ {
		rets, parents = append(rets, cp.rets[as+i]), append(parents, cp.parents[as+i])
	}
	for ; j < bl; j++ {
		rets, parents = append(rets, cp.rets[bs+j]), append(parents, cp.parents[bs+j])
	}
	var r int32
	if int32(len(rets)) < al+bl && len(rets) == 1 {
		r = cp.singleton(parents[0], rets[0])
	} else {
		r = cp.intern(PlanGalopCtxArray, rets, parents)
	}
	cp.merges.set(PlanGalopMergeKey(a, b), r)
	return r
}

// PlanGalopConfig is an ATN configuration: a state, the alternative it predicts and
// its context (an id in the predictor's pool).
type PlanGalopConfig struct {
	state int32
	alt   int32
	ctx   int32
}

func (c PlanGalopConfig) key() uint64 {
	return uint64(uint32(c.ctx))<<32 | uint64(uint32(c.state))<<12 | uint64(uint32(c.alt)&0xfff)
}

// PlanGalopMap maps uint64 keys to int32 values: open addressing, cleared in O(1)
// by bumping the generation. A slot holds its key, value and generation
// together, so a probe reads one cache line.
type PlanGalopMap struct {
	slots []PlanGalopSlot
	gen   uint32
	n     int
}

type PlanGalopSlot struct {
	key uint64
	val int32
	gen uint32
}

func (m *PlanGalopMap) reset() {
	m.gen++
	m.n = 0
	if m.slots == nil || m.gen == 0 {
		m.slots = make([]PlanGalopSlot, 64)
		m.gen = 1
	}
}

func PlanGalopMix(k uint64) uint64 {
	k ^= k >> 33
	k *= 0xff51afd7ed558ccd
	k ^= k >> 33
	return k
}

// put stores v for k unless k is present; it returns the stored value and
// whether k was new.
func (m *PlanGalopMap) put(k uint64, v int32) (int32, bool) {
	if 2*(m.n+1) > len(m.slots) {
		m.grow()
	}
	mask := uint64(len(m.slots) - 1)
	for i := PlanGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			*s = PlanGalopSlot{k, v, m.gen}
			m.n++
			return v, true
		}
		if s.key == k {
			return s.val, false
		}
	}
}

// get returns the value stored for k.
func (m *PlanGalopMap) get(k uint64) (int32, bool) {
	if m.n == 0 {
		return 0, false
	}
	mask := uint64(len(m.slots) - 1)
	for i := PlanGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			return 0, false
		}
		if s.key == k {
			return s.val, true
		}
	}
}

// set stores v for k, replacing any earlier value.
func (m *PlanGalopMap) set(k uint64, v int32) {
	if 2*(m.n+1) > len(m.slots) {
		m.grow()
	}
	mask := uint64(len(m.slots) - 1)
	for i := PlanGalopMix(k) & mask; ; i = (i + 1) & mask {
		s := &m.slots[i]
		if s.gen != m.gen {
			*s = PlanGalopSlot{k, v, m.gen}
			m.n++
			return
		}
		if s.key == k {
			s.val = v
			return
		}
	}
}

func (m *PlanGalopMap) grow() {
	old, gen := m.slots, m.gen
	m.slots = make([]PlanGalopSlot, 2*len(old))
	m.gen = 1
	m.n = 0
	for _, s := range old {
		if s.gen == gen {
			m.put(s.key, s.val)
		}
	}
}

// PlanGalopConfigSet is ANTLR's ATNConfigSet: one configuration per (state, alt),
// whose context is the merge of every context added for it.
type PlanGalopConfigSet struct {
	list []PlanGalopConfig
	at   PlanGalopMap
}

func (s *PlanGalopConfigSet) add(c PlanGalopConfig, cp *PlanGalopCtxPool) {
	k := uint64(uint32(c.state))<<32 | uint64(uint32(c.alt))
	if i, isNew := s.at.put(k, int32(len(s.list))); !isNew {
		s.list[i].ctx = cp.merge(s.list[i].ctx, c.ctx)
		return
	}
	s.list = append(s.list, c)
}

func (s *PlanGalopConfigSet) reset() {
	s.list = s.list[:0]
	s.at.reset()
}

// PlanGalopPredictor holds the scratch state of runtime prediction.
type PlanGalopPredictor struct {
	full    bool
	pool    PlanGalopCtxPool
	busy    PlanGalopMap
	sets    [3]PlanGalopConfigSet
	skipped []PlanGalopConfig
	sorted  []PlanGalopConfig
	multi   bool
	// Scratch for subsets.
	groups     PlanGalopMap
	states     PlanGalopMap
	groupMin   []int32
	stateAlt   []int32
	stateMulti []bool
	// prec is the precedence the decision's rule invocation was called with,
	// and collect says a start state is being computed (see closure).
	prec    int32
	collect bool
	// While the start state of a left-recursive rule's loop entry is
	// computed, filter is set and rule is the decision's rule; suppress
	// says the closure being followed left an outermost call of that rule,
	// and suppressed collects the (state, alt) keys of the configurations
	// it added (ANTLR's precedenceFilterSuppressed). alt1 is scratch for
	// precedenceFilter.
	filter     bool
	rule       int32
	suppress   bool
	suppressed PlanGalopMap
	alt1       PlanGalopMap
}

// busyKey is c's key, met at depth, in the closure's busy set. ANTLR's
// configurations differ in their precedenceFilterSuppressed flag too
// (bit 63). And what c reaches depends on whether precedence predicates
// apply to it (bit 61; see passes): ANTLR's closure marks no state busy on
// an epsilon path, so a state a filtered path met in the decision's own
// rule invocation is followed again when the closure returns to it from
// outside, where the predicates are epsilon. Bit 62 marks loopEntry's keys;
// context ids stay below 1<<29.
func (pr *PlanGalopPredictor) busyKey(c PlanGalopConfig, depth int32) uint64 {
	key := c.key()
	if pr.suppress {
		key |= 1 << 63
	}
	if pr.collect && depth == 0 {
		key |= 1 << 61
	}
	return key
}

// added records, while a start state is filtered, that c was added with
// the current suppress flag.
func (pr *PlanGalopPredictor) added(out *PlanGalopConfigSet, c PlanGalopConfig) {
	out.add(c, &pr.pool)
	if pr.suppress {
		pr.suppressed.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), 0)
	}
}

// matches reports whether consuming transition i accepts token type t.
func PlanGalopMatches(i int32, t int32) bool {
	switch PlanGalopTransKind[i] {
	case PlanGalopKindAtom:
		return PlanGalopTransArg[i] == t
	case PlanGalopKindSet:
		return PlanGalopInSet(PlanGalopSets[PlanGalopTransArg[i]], t)
	}
	return false
}

// PlanGalopInSet reports whether token type t is in set, a list of ranges.
func PlanGalopInSet(set []int32, t int32) bool {
	lo, hi := 0, len(set)/2-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if t < set[2*mid] {
			hi = mid - 1
		} else if t > set[2*mid+1] {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

// closure adds c and every configuration reachable from it without consuming
// a token to out (ANTLR's closureCheckingStopState and closureWork).
//
// Within a rule, what a state reaches without consuming is the same in every
// context, so it comes from the precomputed PlanGalopClos tables; only rule calls,
// rule ends and precedence predicates are handled here. After EOF,
// transitions that match EOF also count as epsilon, which the tables do not
// cover, so that case walks the ATN.
//
// depth is ANTLR's closure depth: rules entered since the decision, less
// rules left (it stays negative once the decision's rule is left). While a
// start state is computed (pr.collect), a precedence predicate met at depth 0,
// in the decision's own rule invocation, passes when its level is at least
// pr.prec, the precedence that invocation was called with, and the path
// stops otherwise; anywhere else it is epsilon, as in ANTLR's prediction.
func (pr *PlanGalopPredictor) closure(c PlanGalopConfig, out *PlanGalopConfigSet, eofAsEpsilon bool, depth int32) {
	if _, isNew := pr.busy.put(pr.busyKey(c, depth), 0); !isNew {
		return
	}
	if PlanGalopStateIsStop[c.state] {
		pr.ruleEnd(c, out, eofAsEpsilon, depth)
		return
	}
	if eofAsEpsilon {
		pr.walk(c, out, depth)
		return
	}
	cp := &pr.pool
	for i := PlanGalopClosStart[c.state]; i < PlanGalopClosStart[c.state+1]; i++ {
		s := PlanGalopClosState[i]
		switch PlanGalopClosKind[i] {
		case 0:
			pr.added(out, PlanGalopConfig{s, c.alt, c.ctx})
		case 1:
			pr.closure(PlanGalopConfig{s, c.alt, cp.singleton(c.ctx, PlanGalopClosArg[i])}, out, false, PlanGalopDeeper(depth))
		case 3:
			if !pr.passes(PlanGalopClosArg[i], depth) {
				continue
			}
			pr.closure(PlanGalopConfig{s, c.alt, c.ctx}, out, false, depth)
		case 4:
			pr.loopEntry(PlanGalopConfig{s, c.alt, c.ctx}, out, depth)
		default:
			pr.closure(PlanGalopConfig{s, c.alt, c.ctx}, out, false, depth)
		}
	}
}

// loopEntry continues c, at the loop entry of a left-recursive rule, into
// the loop and out of it, but not into the loop where canDrop says the
// invocation returned to goes on in it the same way.
func (pr *PlanGalopPredictor) loopEntry(c PlanGalopConfig, out *PlanGalopConfigSet, depth int32) {
	if _, isNew := pr.busy.put(pr.busyKey(c, depth)|1<<62, 0); !isNew {
		return
	}
	for i := PlanGalopTransStart[c.state]; i < PlanGalopTransStart[c.state+1]; i++ {
		if i == PlanGalopTransStart[c.state] && pr.canDrop(c) {
			continue
		}
		pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, c.ctx}, out, false, depth)
	}
}

// canDrop is ANTLR's canDropLoopEntryEdgeInLeftRecursiveRule: c is at the
// loop entry of a left-recursive rule, and every return state of its context
// leads straight back to that entry (PlanGalopStateLoopReturn), so the invocation
// returned to goes on in the loop and c need not enter it.
func (pr *PlanGalopPredictor) canDrop(c PlanGalopConfig) bool {
	return PlanGalopStatePrecLoop[c.state] && pr.pool.canDrop(c.state, c.ctx)
}

// canDrop is canDrop for a configuration at state with context ctx in cp.
func (cp *PlanGalopCtxPool) canDrop(state, ctx int32) bool {
	if cp.isEmpty(ctx) {
		return false
	}
	from, n := cp.start[ctx], cp.length[ctx]
	if cp.rets[from+n-1] == PlanGalopEmptyReturn {
		return false
	}
	for i := int32(0); i < n; i++ {
		if PlanGalopStateLoopReturn[cp.rets[from+i]] != state {
			return false
		}
	}
	return true
}

// PlanGalopDeeper is the depth inside a rule called at depth: one more, unless the
// decision's rule was already left.
func PlanGalopDeeper(depth int32) int32 {
	if depth >= 0 {
		return depth + 1
	}
	return depth
}

// passes says whether a precedence predicate of level, met at depth, lets a
// closure go on (see closure).
func (pr *PlanGalopPredictor) passes(level int32, depth int32) bool {
	return !pr.collect || depth != 0 || level >= pr.prec
}

// walk is closure over the ATN transitions themselves, for after EOF.
func (pr *PlanGalopPredictor) walk(c PlanGalopConfig, out *PlanGalopConfigSet, depth int32) {
	cp := &pr.pool
	if !PlanGalopStateEpsOnly[c.state] {
		pr.added(out, c)
	}
	for i := PlanGalopTransStart[c.state]; i < PlanGalopTransStart[c.state+1]; i++ {
		if i == PlanGalopTransStart[c.state] && pr.canDrop(c) {
			continue
		}
		switch PlanGalopTransKind[i] {
		case PlanGalopKindEpsilon:
			pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
		case PlanGalopKindPrec:
			if pr.passes(PlanGalopTransArg[i], depth) {
				pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
			}
		case PlanGalopKindRule:
			pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, cp.singleton(c.ctx, PlanGalopTransArg[i])}, out, true, PlanGalopDeeper(depth))
		default:
			if PlanGalopMatches(i, -1) {
				pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, c.ctx}, out, true, depth)
			}
		}
	}
}

// ruleEnd continues a configuration at a rule's end: back to each return state
// of its context, or, with the context exhausted, at the end of the start rule
// (LL) or after every call of the rule (SLL).
func (pr *PlanGalopPredictor) ruleEnd(c PlanGalopConfig, out *PlanGalopConfigSet, eofAsEpsilon bool, depth int32) {
	cp := &pr.pool
	{
		if !cp.isEmpty(c.ctx) {
			for i := int32(0); i < cp.length[c.ctx]; i++ {
				ret, parent := cp.rets[cp.start[c.ctx]+i], cp.parents[cp.start[c.ctx]+i]
				if ret == PlanGalopEmptyReturn {
					if pr.full {
						out.add(PlanGalopConfig{c.state, c.alt, 0}, cp)
					} else {
						pr.follow(c, out, eofAsEpsilon, depth-1)
					}
					continue
				}
				pr.closure(PlanGalopConfig{ret, c.alt, parent}, out, eofAsEpsilon, depth-1)
			}
			return
		}
		if pr.full {
			// End of the start rule in full context.
			out.add(c, cp)
			return
		}
		pr.follow(c, out, eofAsEpsilon, depth-1)
	}
}

// follow continues a configuration at a rule's end after every call of the
// rule (ANTLR's rule-stop follow links, used when the caller is unknown). A
// rule nobody calls keeps the configuration at its end.
func (pr *PlanGalopPredictor) follow(c PlanGalopConfig, out *PlanGalopConfigSet, eofAsEpsilon bool, depth int32) {
	rule := PlanGalopStateRule[c.state]
	if PlanGalopFollowStart[rule] == PlanGalopFollowStart[rule+1] {
		pr.added(out, c)
		return
	}
	for i := PlanGalopFollowStart[rule]; i < PlanGalopFollowStart[rule+1]; i++ {
		if pr.filter && rule == pr.rule && PlanGalopFollowOuter[i] && !pr.suppress {
			// Past an outermost call of the decision's rule, the precedence
			// filter spares what the closure reaches.
			pr.suppress = true
			pr.closure(PlanGalopConfig{PlanGalopFollowState[i], c.alt, c.ctx}, out, eofAsEpsilon, depth)
			pr.suppress = false
			continue
		}
		pr.closure(PlanGalopConfig{PlanGalopFollowState[i], c.alt, c.ctx}, out, eofAsEpsilon, depth)
	}
}

func PlanGalopUniqueAlt(list []PlanGalopConfig) int32 {
	alt := int32(0)
	for _, c := range list {
		if alt == 0 {
			alt = c.alt
		} else if c.alt != alt {
			return 0
		}
	}
	return alt
}

// reach computes the configurations reachable from closure by consuming t
// (ANTLR's computeReachSet). With group set, t is an opening bracket and the
// whole bracketed group is consumed: a configuration moves to the states after
// the matching closer. The result is in out; a non-zero return is an
// alternative decided early.
func (pr *PlanGalopPredictor) reach(closure *PlanGalopConfigSet, t int32, group bool, intermediate, out *PlanGalopConfigSet) int32 {
	cp := &pr.pool
	intermediate.reset()
	pr.skipped = pr.skipped[:0]
	for _, c := range closure.list {
		if PlanGalopStateIsStop[c.state] {
			if pr.full || t == -1 {
				pr.skipped = append(pr.skipped, c)
			}
			continue
		}
		for i := PlanGalopTransStart[c.state]; i < PlanGalopTransStart[c.state+1]; i++ {
			k := PlanGalopTransKind[i]
			if k != PlanGalopKindAtom && k != PlanGalopKindSet || !PlanGalopMatches(i, t) {
				continue
			}
			if !group {
				intermediate.add(PlanGalopConfig{PlanGalopTransTarget[i], c.alt, c.ctx}, cp)
				continue
			}
			for j := PlanGalopAfterStart[i]; j < PlanGalopAfterStart[i+1]; j++ {
				intermediate.add(PlanGalopConfig{PlanGalopAfterState[j], c.alt, c.ctx}, cp)
			}
		}
	}
	if len(pr.skipped) == 0 && t != -1 {
		if alt := PlanGalopUniqueAlt(intermediate.list); alt != 0 {
			return alt
		}
	}
	out.reset()
	pr.busy.reset()
	for _, c := range intermediate.list {
		pr.closure(c, out, t == -1, 0)
	}
	if t == -1 {
		// After EOF only configurations at the end of a rule matter.
		n := 0
		for _, c := range out.list {
			if PlanGalopStateIsStop[c.state] {
				out.list[n] = c
				n++
			}
		}
		out.list = out.list[:n]
		out.at.reset()
		for i, c := range out.list {
			out.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
		}
	}
	if len(pr.skipped) > 0 {
		inStop := false
		for _, c := range out.list {
			if PlanGalopStateIsStop[c.state] {
				inStop = true
				break
			}
		}
		if !pr.full || !inStop {
			for _, c := range pr.skipped {
				out.add(c, cp)
			}
		}
	}
	return 0
}

// subsets computes ANTLR's conflicting alternative subsets of list, a set's
// configurations (grouped by state and context). It returns the lowest
// alternative common to all subsets' minimums (0 if they differ), sets
// pr.multi when some subset has more than one alternative, and reports
// whether some state is associated with exactly one alternative.
func (pr *PlanGalopPredictor) subsets(list []PlanGalopConfig) (single int32, stateWithOneAlt bool) {
	// A configuration set holds one configuration per (state, alt), so two
	// configurations in the same (state, ctx) group always differ in alt.
	pr.groups.reset()
	pr.states.reset()
	pr.groupMin = pr.groupMin[:0]
	pr.stateAlt = pr.stateAlt[:0]
	pr.stateMulti = pr.stateMulti[:0]
	pr.multi = false
	for _, c := range list {
		g, isNew := pr.groups.put(uint64(uint32(c.state))<<32|uint64(uint32(c.ctx)), int32(len(pr.groupMin)))
		if isNew {
			pr.groupMin = append(pr.groupMin, c.alt)
		} else {
			pr.multi = true
			pr.groupMin[g] = min(pr.groupMin[g], c.alt)
		}
		s, isNew := pr.states.put(uint64(uint32(c.state)), int32(len(pr.stateAlt)))
		if isNew {
			pr.stateAlt = append(pr.stateAlt, c.alt)
			pr.stateMulti = append(pr.stateMulti, false)
		} else if pr.stateAlt[s] != c.alt {
			pr.stateMulti[s] = true
		}
	}
	for _, m := range pr.stateMulti {
		if !m {
			stateWithOneAlt = true
			break
		}
	}
	for _, m := range pr.groupMin {
		if single == 0 {
			single = m
		} else if single != m {
			return 0, stateWithOneAlt
		}
	}
	return single, stateWithOneAlt
}

// conflict reports whether SLL prediction stops at list, a set with more than
// one alternative: every configuration is at a rule's end, or the
// alternatives conflict (ANTLR's hasSLLConflictTerminatingPrediction).
func (pr *PlanGalopPredictor) conflict(list []PlanGalopConfig) bool {
	_, oneAlt := pr.subsets(list)
	return PlanGalopAllInStop(list) || (pr.multi && !oneAlt)
}

func PlanGalopAllInStop(list []PlanGalopConfig) bool {
	for _, c := range list {
		if !PlanGalopStateIsStop[c.state] {
			return false
		}
	}
	return true
}

// PlanGalopDFAState is a state of a decision's SLL lookahead DFA, cached across
// parses as ANTLR caches its DFA. Walking existing edges takes no lock; new
// states are computed under PlanGalopDFA.mu.
type PlanGalopDFAState struct {
	configs  []PlanGalopConfig
	alt      int32
	conflict int32
	// alts are a conflict's alternatives (bit a for alternative a), 0 when
	// one is past 63.
	alts  uint64
	edges []atomic.Pointer[PlanGalopDFAState]
}

// PlanGalopDFAGen is one generation of the SLL DFA cache: every decision's start
// state, the states by configurations, and the predictor whose context pool
// gives the configurations' contexts their meaning. Its pool is never reset,
// so cached configurations keep meaning the same contexts; the cache starts
// over by replacing the whole generation.
type PlanGalopDFAGen struct {
	starts []atomic.Pointer[PlanGalopDFAState]
	// precStarts are the start states of the decisions of left-recursive
	// rules, one per decision and precedence (see startAt), at
	// d*(PlanGalopMaxPrec+1)+prec.
	precStarts []atomic.Pointer[PlanGalopDFAState]
	states     map[string]*PlanGalopDFAState
	pr         PlanGalopPredictor
	key        []byte
}

// PlanGalopDFA is the process's SLL DFA cache. Only the current generation grows.
// Once it holds PlanGalopDFAMaxStates states or PlanGalopDFAMaxContexts contexts, it is
// replaced by an empty one, and from then on it only serves the predictions
// already walking it: one that needs a state it lacks finishes uncached
// (predictSLLUncached). So no generation passes the bound (its contexts by at
// most one step's worth), and since the cache only saves work, no answer
// changes. peak is the most states a replaced generation held, and resets
// counts replacements.
//
// The full-context cache (PlanGalopFullCache) stops growing instead of starting
// over: full-context predictions are rare, and an uncached one costs about
// what building its states does. SLL predictions are what every runtime
// decision makes, and a cache that stops growing leaves a long-lived process
// predicting uncached for whatever its first inputs did not reach. On a
// stream of 27,700 parses of distinct GALA code on one goroutine, stopping
// cost 1.25 times the time of an unbounded cache (3.3 times over tokens
// alone), starting over 1.02 times (1.8 times); both halve the peak memory or
// better. On eight goroutines, where new states wait for one lock, stopping
// was the faster (0.7 and 0.5 times, against 1.1 and 2.2).
var PlanGalopDFA struct {
	mu     sync.Mutex
	gen    atomic.Pointer[PlanGalopDFAGen]
	peak   int
	resets int
}

// PlanGalopDFAMaxStates and PlanGalopDFAMaxContexts bound each generation of the SLL DFA
// cache. They are read under PlanGalopDFA.mu; set them before parsing starts, if at
// all. The defaults are three to four times what parsing the GALA compiler's
// sources and other GALA code over tokens alone (-Xno-brackets) leaves in the
// cache: about 16,000 states and 740,000 contexts, some 100 MB.
var (
	PlanGalopDFAMaxStates   = 1 << 16
	PlanGalopDFAMaxContexts = 1 << 21
)

// PlanGalopDFAError marks an edge on which no alternative is viable.
var PlanGalopDFAError = &PlanGalopDFAState{}

// PlanGalopNewDFAGen returns an empty generation of the SLL DFA cache.
func PlanGalopNewDFAGen() *PlanGalopDFAGen {
	g := &PlanGalopDFAGen{starts: make([]atomic.Pointer[PlanGalopDFAState], len(PlanGalopDecisionState)), precStarts: make([]atomic.Pointer[PlanGalopDFAState], len(PlanGalopDecisionState)*(PlanGalopMaxPrec+1)), states: map[string]*PlanGalopDFAState{}}
	g.pr.pool.reset(true)
	return g
}

func init() {
	PlanGalopDFA.gen.Store(PlanGalopNewDFAGen())
}

// PlanGalopDFAStats reports the SLL DFA cache: the states of the current
// generation, the most states any generation held, and how many times the
// cache started over.
func PlanGalopDFAStats() (states, peak, resets int) {
	PlanGalopDFA.mu.Lock()
	defer PlanGalopDFA.mu.Unlock()
	states = len(PlanGalopDFA.gen.Load().states)
	return states, max(PlanGalopDFA.peak, states), PlanGalopDFA.resets
}

// grows reports whether g may add to itself: it is the current generation
// and below its bound. Call it under PlanGalopDFA.mu.
func (g *PlanGalopDFAGen) grows() bool {
	return g == PlanGalopDFA.gen.Load() && len(g.states) < PlanGalopDFAMaxStates && len(g.pr.pool.kind) < PlanGalopDFAMaxContexts
}

// checkFull replaces g, the current generation, with an empty one once it
// has reached its bound. Call it under PlanGalopDFA.mu.
func (g *PlanGalopDFAGen) checkFull() {
	if g != PlanGalopDFA.gen.Load() || g.grows() {
		return
	}
	PlanGalopDFA.peak = max(PlanGalopDFA.peak, len(g.states))
	PlanGalopDFA.resets++
	PlanGalopDFA.gen.Store(PlanGalopNewDFAGen())
}

// intern returns decision d's state in g for the configurations in set.
func (g *PlanGalopDFAGen) intern(d int, set *PlanGalopConfigSet) *PlanGalopDFAState {
	return PlanGalopInternState(g.states, &g.pr, &g.key, d, set, PlanGalopEdges)
}

// PlanGalopSortConfigs sorts configurations by state, then alternative: the order
// a cached state keeps them in.
func PlanGalopSortConfigs(s []PlanGalopConfig) {
	slices.SortFunc(s, func(a, b PlanGalopConfig) int {
		if a.state != b.state {
			return int(a.state - b.state)
		}
		return int(a.alt - b.alt)
	})
}

// PlanGalopInternState returns the state in states for the configurations in set,
// adding it if new. A state keeps its configurations sorted by state and
// alternative; its key is that list, after decision d when d >= 0. pr and key
// are scratch, owned by whoever owns states. A new state has edges edges.
func PlanGalopInternState(states map[string]*PlanGalopDFAState, pr *PlanGalopPredictor, key *[]byte, d int, set *PlanGalopConfigSet, edges int) *PlanGalopDFAState {
	s := append(pr.sorted[:0], set.list...)
	pr.sorted = s
	PlanGalopSortConfigs(s)
	k := (*key)[:0]
	if d >= 0 {
		k = binary.LittleEndian.AppendUint32(k, uint32(d))
	}
	for _, c := range s {
		k = binary.LittleEndian.AppendUint32(k, uint32(c.state))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.alt))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.ctx))
	}
	*key = k
	if st, ok := states[string(k)]; ok {
		return st
	}
	st := &PlanGalopDFAState{configs: slices.Clone(s), edges: make([]atomic.Pointer[PlanGalopDFAState], edges)}
	states[string(k)] = st
	return st
}

// startSLL puts the start configurations of decision d into cur (ANTLR's
// computeStartState in SLL mode).
func (pr *PlanGalopPredictor) startSLL(d int, cur *PlanGalopConfigSet) {
	pr.full = false
	cur.reset()
	pr.busy.reset()
	s := PlanGalopDecisionState[d]
	pr.collect = true
	pr.filter, pr.rule = PlanGalopDecisionLoopEntry[d], PlanGalopStateRule[s]
	if pr.filter {
		pr.suppressed.reset()
	}
	for i := PlanGalopTransStart[s]; i < PlanGalopTransStart[s+1]; i++ {
		pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], i - PlanGalopTransStart[s] + 1, 0}, cur, false, 0)
	}
	pr.collect = false
	if pr.filter {
		pr.precedenceFilter(cur)
		pr.filter = false
	}
}

// precedenceFilter is ANTLR's applyPrecedenceFilter, for the start state of a
// left-recursive rule's loop entry: a configuration that leaves the loop is
// dropped where one that goes on in it (alternative 1) is at the same state
// with the same context, since leaving goes on in an enclosing invocation the
// same way, unless it got there past an outermost call of the rule. The
// precedence predicates of alternative 1 were evaluated by the closure.
func (pr *PlanGalopPredictor) precedenceFilter(cur *PlanGalopConfigSet) {
	pr.alt1.reset()
	for _, c := range cur.list {
		if c.alt == 1 {
			pr.alt1.put(uint64(uint32(c.state)), c.ctx)
		}
	}
	n := 0
	for _, c := range cur.list {
		if c.alt != 1 {
			_, spared := pr.suppressed.get(uint64(uint32(c.state))<<32 | uint64(uint32(c.alt)))
			if ctx, ok := pr.alt1.get(uint64(uint32(c.state))); ok && ctx == c.ctx && !spared {
				continue
			}
		}
		cur.list[n] = c
		n++
	}
	cur.list = cur.list[:n]
	cur.at.reset()
	for i, c := range cur.list {
		cur.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
	}
}

// stepSLL moves the configurations in cur over token t, or with group set
// over the bracketed group t opens (ANTLR's computeTargetState in SLL mode).
// It returns the state that ends the prediction (an alternative, an SLL
// conflict or PlanGalopDFAError), or nil when the prediction goes on from the
// configurations in next.
func (pr *PlanGalopPredictor) stepSLL(cur *PlanGalopConfigSet, t int32, group bool, intermediate, next *PlanGalopConfigSet) *PlanGalopDFAState {
	if alt := pr.reach(cur, t, group, intermediate, next); alt != 0 {
		return &PlanGalopDFAState{alt: alt}
	}
	if len(next.list) == 0 {
		return PlanGalopDFAError
	}
	if alt := PlanGalopUniqueAlt(next.list); alt != 0 {
		return &PlanGalopDFAState{alt: alt}
	}
	if !pr.conflict(next.list) {
		return nil
	}
	// An SLL conflict: ANTLR's SLL answer is the lowest conflicting alternative.
	low := next.list[0].alt
	var alts uint64
	wide := false
	for _, c := range next.list {
		low = min(low, c.alt)
		if c.alt > 63 {
			wide = true
		} else {
			alts |= 1 << c.alt
		}
	}
	if wide {
		alts = 0
	}
	return &PlanGalopDFAState{conflict: low, alts: alts}
}

// start returns decision d's start state in g, computing it once; nil when
// it is not cached and g may not grow.
func (g *PlanGalopDFAGen) start(d int) *PlanGalopDFAState {
	PlanGalopDFA.mu.Lock()
	defer PlanGalopDFA.mu.Unlock()
	if st := g.starts[d].Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	cur := &g.pr.sets[0]
	g.pr.startSLL(d, cur)
	st := g.intern(d, cur)
	g.starts[d].Store(st)
	g.checkFull()
	return st
}

// startAt is start for decision d of a left-recursive rule, whose start state
// depends on the precedence prec its rule was called with: one cached state
// per precedence, as ANTLR's precedence DFA keeps.
func (g *PlanGalopDFAGen) startAt(d int, prec int32) *PlanGalopDFAState {
	at := &g.precStarts[d*(PlanGalopMaxPrec+1)+int(prec)]
	if st := at.Load(); st != nil {
		return st
	}
	PlanGalopDFA.mu.Lock()
	defer PlanGalopDFA.mu.Unlock()
	if st := at.Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	cur := &g.pr.sets[0]
	g.pr.prec = prec
	g.pr.startSLL(d, cur)
	st := g.intern(d, cur)
	at.Store(st)
	g.checkFull()
	return st
}

// next computes and caches the edge of from, a state of g, on symbol sym:
// token t, or with group set the bracketed group t opens. It returns nil
// when the edge is not cached and g may not grow.
func (g *PlanGalopDFAGen) next(d int, from *PlanGalopDFAState, sym int, t int32, group bool) *PlanGalopDFAState {
	PlanGalopDFA.mu.Lock()
	defer PlanGalopDFA.mu.Unlock()
	if st := from.edges[sym].Load(); st != nil {
		return st
	}
	if !g.grows() {
		return nil
	}
	pr := &g.pr
	pr.full = false
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	cur.reset()
	for _, c := range from.configs {
		cur.add(c, &pr.pool)
	}
	st := pr.stepSLL(cur, t, group, intermediate, next)
	if st == nil {
		st = g.intern(d, next)
	}
	from.edges[sym].Store(st)
	g.checkFull()
	return st
}

// symbolAt reads the input at i for a prediction of decision d: the token t,
// its DFA symbol, whether that symbol is the bracketed group an opener at i
// starts (with p.group, as PlanGalopBracketMatch paired them), and where the input
// after it starts.
func (p *PlanGalopParser) symbolAt(d, i int) (t int32, sym int, isGroup bool, after int) {
	// The tokens end with EOF: the native flavor's run rejects a slice without
	// it, and the antlr flavor's NewPlanGalopParser reads its stream up to EOF. EOF never
	// advances i, and a group jump lands just past its closer, on EOF at the
	// latest, so i stays in range.
	t = p.types[i]
	if t < -1 || int(t) > PlanGalopMaxTokenType {
		p.noViableAlt(d)
	}
	if og := PlanGalopOpenerSym[t+1]; p.group && og >= 0 && p.pairs[i] >= 0 {
		return t, PlanGalopMaxTokenType + 2 + int(og), true, int(p.pairs[i]) + 1
	}
	if t != -1 {
		i++
	}
	return t, int(t) + 1, false, i
}

// peekAt notes that prediction read token i: peek is the furthest token an
// error replay's predictions read, as ANTLR's lazy token stream fetches
// them. i may be past EOF, which reads EOF (see PlanGalopRecovery.read).
func (p *PlanGalopParser) peekAt(i int) {
	if i > p.peek {
		p.peek = i
	}
}

// adaptivePredict predicts decision d as ANTLR's SLL prediction does, over
// the cached DFA, reading each bracketed group as one symbol unless p.group
// is off. That over-approximates SLL: every path over the tokens has a path
// over the groups, so an alternative ruled out here is ruled out in SLL and
// in LL, and a unique answer is ANTLR's. A conflict goes to onConflict with
// its smallest alternative: a first pass that succeeds with such choices is
// ANTLR's LL parse, and a wrong one is repaired. Where the cache may not grow
// (see PlanGalopDFA), the prediction finishes uncached.
func (p *PlanGalopParser) adaptivePredict(d int) int {
	p.stats.Predictions++
	g := PlanGalopDFA.gen.Load()
	var st *PlanGalopDFAState
	if PlanGalopDecisionPrecedence[d] {
		st = g.startAt(d, p.prec)
	} else if st = g.starts[d].Load(); st == nil {
		st = g.start(d)
	}
	if st == nil {
		return p.predictSLLUncached(d)
	}
	for i := p.pos; ; {
		p.peekAt(i)
		t, sym, isGroup, after := p.symbolAt(d, i)
		next := st.edges[sym].Load()
		if next == nil {
			if next = g.next(d, st, sym, t, isGroup); next == nil {
				return p.predictSLLUncached(d)
			}
		}
		if alt, done := p.settleSLL(d, next); done {
			return alt
		}
		st, i = next, after
	}
}

// settleSLL ends a prediction of decision d at st when st ends it: with a
// syntax error (or ANTLR's fallback; see deadEnd), an alternative or a
// conflict.
func (p *PlanGalopParser) settleSLL(d int, st *PlanGalopDFAState) (int, bool) {
	switch {
	case st == PlanGalopDFAError:
		return p.deadEnd(d), true
	case st.alt > 0:
		return int(st.alt), true
	case st.conflict > 0:
		return p.onConflict(d, int(st.conflict), st.alts), true
	}
	return 0, false
}

// predictSLLUncached predicts decision d as adaptivePredict does, with the
// parser's own predictor and no cache. Each step starts from the
// configurations sorted and added in the order a cached state keeps them, so
// it computes what the cache would.
func (p *PlanGalopParser) predictSLLUncached(d int) int {
	pr := &p.pred
	pr.pool.reset(true)
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	pr.prec = p.prec
	pr.startSLL(d, next)
	for i := p.pos; ; {
		p.peekAt(i)
		s := append(pr.sorted[:0], next.list...)
		pr.sorted = s
		PlanGalopSortConfigs(s)
		cur.reset()
		for _, c := range s {
			cur.add(c, &pr.pool)
		}
		t, _, isGroup, after := p.symbolAt(d, i)
		if st := pr.stepSLL(cur, t, isGroup, intermediate, next); st != nil {
			alt, _ := p.settleSLL(d, st)
			return alt
		}
		i = after
	}
}

// PlanGalopEdges is the number of DFA edges per state: one per token type and EOF,
// then one per opening bracket for the group it opens.
const PlanGalopEdges = PlanGalopMaxTokenType + 2 + PlanGalopOpenerCount

// PlanGalopBracketMatch pairs the brackets of types into m: m[i] is the index of
// the closer of the opener at i, or -1. An opener with no well-nested closer
// (the input is not in the language) is left at -1, and prediction reads it
// as a token. A parse pairs brackets only when it reads groups (p.group).
// balanced says every bracket is paired: every sentence of the language is
// (see brackets), so input that is not cannot parse.
func PlanGalopBracketMatch(types []int32, m []int32) (pairs []int32, balanced bool) {
	m = slices.Grow(m[:0], len(types))[:len(types)]
	var open []int32
	balanced = true
	for i, t := range types {
		m[i] = -1
		if t < -1 || int(t) > PlanGalopMaxTokenType {
			continue
		}
		if PlanGalopOpenerSym[t+1] >= 0 {
			open = append(open, int32(i))
			continue
		}
		if !PlanGalopIsCloser[t+1] {
			continue
		}
		if len(open) == 0 {
			balanced = false
			continue
		}
		top := open[len(open)-1]
		if PlanGalopOpenerCloser[PlanGalopOpenerSym[types[top]+1]] == t {
			m[top] = int32(i)
			open = open[:len(open)-1]
		} else {
			// A closer of the wrong kind: no opener still open can close
			// around it.
			open = open[:0]
			balanced = false
		}
	}
	return m, balanced && len(open) == 0
}

// onConflict settles an SLL conflict whose lowest conflicting alternative is
// sllAlt and whose alternatives are alts (0 when one is past 63). The SLL
// pass takes sllAlt; this stays small enough to inline.
func (p *PlanGalopParser) onConflict(d int, sllAlt int, alts uint64) int {
	if p.ll || p.rp.on || p.first {
		return p.onConflictSlow(d, sllAlt, alts)
	}
	p.rp.seen++
	return sllAlt
}

// onConflictSlow is onConflict outside the SLL pass: a guessing first pass
// records the conflict as a guess point (see guessSource), LL mode runs
// full-context prediction, and a repair pass replays a recorded conflict or
// records a new one.
func (p *PlanGalopParser) onConflictSlow(d int, sllAlt int, alts uint64) int {
	if p.first {
		if alts == 0 {
			p.gs.wide = true
			return sllAlt
		}
		return p.guess(alts)
	}
	if p.ll {
		if alt := p.rp.knownAt(d, p.pos, p.stack); alt > 0 {
			return alt
		}
		return p.predictLL(d)
	}
	r := &p.rp
	i := r.seq
	r.seq++
	if i < len(r.recs) {
		c := &r.recs[i]
		if int(c.d) != d || int(c.pos) != p.pos {
			panic("galop: a repair pass left the parse it replays")
		}
		return int(c.alt)
	}
	from := len(r.stacks)
	r.stacks = append(r.stacks, p.stack...)
	r.recs = append(r.recs, PlanGalopConflict{d: int32(d), pos: int32(p.pos), alt: int32(sllAlt), stackFrom: int32(from), stackTo: int32(len(r.stacks))})
	return sllAlt
}

// PlanGalopConflict is an SLL conflict a repair pass met: the decision, the token
// it was predicted at, the alternative the parse takes there, the parser's
// call stack at that point (r.stacks[stackFrom:stackTo]), and its LL answer
// once known (0: not checked, -1: no alternative is viable, err says why).
type PlanGalopConflict struct {
	d, pos, alt, known int32
	stackFrom, stackTo int32
	err                error
}

// PlanGalopRepair is the state of a repair (see llParse): how many conflicts the
// SLL pass met, and the records and progress of the repair passes.
type PlanGalopRepair struct {
	seen   int
	on     bool
	seq    int
	recs   []PlanGalopConflict
	stacks []int32
	// byPos indexes recs by decision and token while an error replay (see
	// antlrError) reads their LL answers; nil otherwise.
	byPos map[uint64][]int32
}

// indexRecs indexes recs by decision and token for knownAt.
func (r *PlanGalopRepair) indexRecs() {
	r.byPos = make(map[uint64][]int32, len(r.recs))
	for i, c := range r.recs {
		k := uint64(c.pos)<<32 | uint64(c.d)
		r.byPos[k] = append(r.byPos[k], int32(i))
	}
}

// knownAt is the LL answer a repair recorded for decision d at token pos with
// call stack stack, or 0.
func (r *PlanGalopRepair) knownAt(d, pos int, stack []int32) int {
	for _, i := range r.byPos[uint64(pos)<<32|uint64(d)] {
		c := &r.recs[i]
		if c.known > 0 && slices.Equal(r.stacks[c.stackFrom:c.stackTo], stack) {
			return int(c.known)
		}
	}
	return 0
}

// A repair stops and falls back to the whole-input LL rerun when the passes
// after the first would replay more tokens in total than the input holds, so
// that a file it cannot repair costs about two SLL passes more than the rerun;
// PlanGalopRepairPasses also bounds the number of passes. PlanGalopRepairBackward is how
// many conflicts a pass checks backwards from its error before it checks the
// rest forwards from the start, as LL mode meets them. The conflict to switch
// is almost always within a few of the error (on the GALA and held-out
// corpora and 10,000 mutants of them, at most 5 back), and a parse that fails
// for good makes at most PlanGalopRepairBackward full-context predictions more than
// the rerun would.
const (
	PlanGalopRepairPasses   = 8
	PlanGalopRepairBackward = 8
)

// llParse returns the parse ANTLR's LL prediction gives, after the SLL pass
// failed with sllErr. With repair it repairs the failed parse instead of
// running full-context prediction at every conflict; repair needs an entry
// rule that ends with EOF.
//
// At an SLL conflict, ANTLR's LL prediction is the lowest alternative that
// can still complete the parse: configurations with the same state and stack
// have the same future, and SLL configurations over-approximate LL ones. So a
// parse that reaches EOF proves its choice at every conflict where it took the
// lowest alternative, and only where it takes another one does it need LL
// prediction, which then decides. Each pass replays the parse with the
// choices so far; after a syntax error, switchConflict changes one. When it
// finds nothing to change, LL fails too: at the earliest conflict where no
// alternative is viable, or where this pass failed.
func (p *PlanGalopParser) llParse(rule func(antlr.ParserRuleContext, int) antlr.ParserRuleContext, repair bool, sllErr error) (antlr.ParserRuleContext, error) {
	if p.ll {
		// The failed pass ran in LL mode already (see llFirst).
		return nil, sllErr
	}
	if repair {
		if p.rp.seen == 0 {
			// No conflict before the error: every decision was LL's, so LL
			// mode fails at the same token.
			return nil, sllErr
		}
		r := &p.rp
		r.on = true
		defer func() { r.on = false }()
		r.recs, r.stacks = r.recs[:0], r.stacks[:0]
		replayed := 0 // tokens up to the errors of the failed passes after the first
		for pass := 0; pass < PlanGalopRepairPasses; pass++ {
			r.seq = 0
			root, err := p.attempt(rule)
			if err == nil {
				return root, nil
			}
			if pass > 0 {
				replayed += p.pos
			}
			switched, dead := p.switchConflict()
			// The next pass replays about as far as this one did.
			if switched && replayed+p.pos > len(p.types) {
				break
			}
			switch {
			case switched:
			case dead != nil:
				// LL mode stops at that conflict; so does the parse.
				p.pos = int(dead.pos)
				return nil, dead.err
			default:
				return root, err
			}
		}
		r.on = false
	}
	p.ll = true
	defer func() { p.ll = false }()
	return p.attempt(rule)
}

// switchConflict checks the conflicts of the pass that just failed and
// switches one whose LL answer differs from the alternative taken: the latest
// such among the PlanGalopRepairBackward before the error, or else the earliest of
// the rest. When none differs it returns the earliest conflict where no
// alternative is viable, if any: there LL mode fails. (Scanning backwards,
// the last dead one seen is the earliest; the forward scan returns its first.)
func (p *PlanGalopParser) switchConflict() (switched bool, dead *PlanGalopConflict) {
	r := &p.rp
	budget := PlanGalopRepairBackward
	i := r.seq - 1
	for ; i >= 0; i-- {
		c := &r.recs[i]
		if c.known == 0 {
			if budget == 0 {
				break
			}
			budget--
			p.checkConflict(c)
		}
		switch {
		case c.known < 0:
			dead = c
		case c.known != c.alt:
			p.switchTo(i)
			return true, nil
		}
	}
	// Forwards over the conflicts the backward scan did not check. A dead
	// one with only agreeing conflicts before it is where LL mode fails.
	for j := 0; j <= i; j++ {
		c := &r.recs[j]
		if c.known == 0 {
			p.checkConflict(c)
		}
		switch {
		case c.known < 0:
			return false, c
		case c.known != c.alt:
			p.switchTo(j)
			return true, nil
		}
	}
	return false, dead
}

// switchTo makes conflict i take its LL answer and drops the records after
// it, which the next pass records again.
func (p *PlanGalopParser) switchTo(i int) {
	r := &p.rp
	c := &r.recs[i]
	c.alt = c.known
	r.recs, r.stacks = r.recs[:i+1], r.stacks[:c.stackTo]
}

// checkConflict computes c's LL answer with the parser at c's token and stack.
func (p *PlanGalopParser) checkConflict(c *PlanGalopConflict) {
	pos, stack := p.pos, p.stack
	defer func() {
		p.pos, p.stack = pos, stack
		if e := recover(); e != nil {
			se, ok := e.(*PlanGalopSyntaxError)
			if !ok {
				panic(e)
			}
			c.known, c.err = -1, se
		}
	}()
	p.pos, p.stack = int(c.pos), p.rp.stacks[c.stackFrom:c.stackTo:c.stackTo]
	c.known = int32(p.predictLL(int(c.d)))
}

// PlanGalopGuess is a guess point of the first pass: the alternatives no test
// ruled out (bit a for alternative a) and the one taken.
type PlanGalopGuess struct {
	alts uint64
	cur  uint8
}

// PlanGalopGuesses records the guess points of the first pass: seq counts those met
// by the current pass, the first forced of pts replay their choice, and wide
// says a guess point had an alternative past 63, which the search cannot record.
type PlanGalopGuesses struct {
	seq    int
	forced int
	pts    []PlanGalopGuess
	wide   bool
}

// The search stops after PlanGalopGuessReplays replays; once its replays have read
// PlanGalopGuessTokens times the input's tokens, or PlanGalopGuessFloor tokens for a short
// input (a replay rereads the input from its start, so k wrong guesses far into
// a large input cost k passes); or after PlanGalopGuessStall replays in a row that
// fail no further into the input than the furthest failure so far. A search
// that will succeed fixes its wrong guesses one by one and gets further with
// each; on input outside the language every replay fails about where the
// first pass did. Stopping early is always exact: what follows the search is.
const (
	PlanGalopGuessReplays = 64
	PlanGalopGuessTokens  = 4
	PlanGalopGuessFloor   = 16384
	PlanGalopGuessStall   = 16
)

// guess takes the smallest alternative in alts, through guessPoint when alts
// has more than one. It stays small enough to inline.
func (p *PlanGalopParser) guess(alts uint64) int {
	if alts&(alts-1) == 0 {
		return bits.TrailingZeros64(alts)
	}
	return p.guessPoint(alts)
}

// guessPoint records a guess point and takes its smallest alternative, or
// replays the choice the search forces there.
func (p *PlanGalopParser) guessPoint(alts uint64) int {
	g := &p.gs
	i := g.seq
	g.seq++
	if i < g.forced {
		return int(g.pts[i].cur)
	}
	low := bits.TrailingZeros64(alts)
	g.pts = append(g.pts[:i], PlanGalopGuess{alts: alts, cur: uint8(low)})
	return low
}

// guessed says the first pass made a guess, so it may have taken another
// path than SLL prediction would.
func (g *PlanGalopGuesses) guessed() bool {
	return len(g.pts) > 0 || g.wide
}

// next makes the latest guess point with an untried alternative take the
// next one, forcing the choices before it; false when none is left.
func (g *PlanGalopGuesses) next() bool {
	for j := min(g.seq, len(g.pts)) - 1; j >= 0; j-- {
		pt := &g.pts[j]
		if rest := pt.alts &^ (uint64(2)<<pt.cur - 1); rest != 0 {
			pt.cur = uint8(bits.TrailingZeros64(rest))
			g.pts = g.pts[:j+1]
			g.forced = j + 1
			return true
		}
	}
	return false
}

// search replays the failed first pass with the next choice sequences, as
// described above; ok is false when it stopped without a parse.
func (p *PlanGalopParser) search(rule func(antlr.ParserRuleContext, int) antlr.ParserRuleContext) (root antlr.ParserRuleContext, ok bool) {
	g := &p.gs
	defer func() { g.forced, g.pts = 0, g.pts[:0] }()
	budget := max(PlanGalopGuessTokens*len(p.types), PlanGalopGuessFloor)
	furthest, stall := p.pos, 0
	for replays := 0; replays < PlanGalopGuessReplays && !g.wide && g.next(); replays++ {
		root, err := p.attempt(rule)
		if err == nil {
			return root, true
		}
		if budget -= p.pos + 1; budget <= 0 {
			break
		}
		if p.pos > furthest {
			furthest, stall = p.pos, 0
		} else if stall++; stall >= PlanGalopGuessStall {
			break
		}
	}
	return nil, false
}

// predictAt is adaptivePredict for decision d of a left-recursive rule called
// with precedence prec.
func (p *PlanGalopParser) predictAt(d int, prec int32) int {
	p.prec = prec
	return p.adaptivePredict(d)
}

// startLL fills cur with the closure of decision d's alternatives, with the
// call stack stack as the outer context (ANTLR's start state of full-context
// prediction).
func (pr *PlanGalopPredictor) startLL(d int, stack []int32, cur *PlanGalopConfigSet) {
	cp := &pr.pool
	outer := int32(0)
	for _, ret := range stack {
		outer = cp.singleton(outer, ret)
	}
	cur.reset()
	pr.busy.reset()
	s := PlanGalopDecisionState[d]
	pr.collect = true
	for i := PlanGalopTransStart[s]; i < PlanGalopTransStart[s+1]; i++ {
		pr.closure(PlanGalopConfig{PlanGalopTransTarget[i], i - PlanGalopTransStart[s] + 1, outer}, cur, false, 0)
	}
	pr.collect = false
}

// stepLL moves full-context prediction from cur past token t into next and
// applies ANTLR's stopping rule: the alternative it picks, -1 when no
// alternative is viable, or 0 to read another token.
func (pr *PlanGalopPredictor) stepLL(cur *PlanGalopConfigSet, t int32, intermediate, next *PlanGalopConfigSet) int32 {
	if alt := pr.reach(cur, t, false, intermediate, next); alt != 0 {
		return alt
	}
	if len(next.list) == 0 {
		return -1
	}
	if alt := PlanGalopUniqueAlt(next.list); alt != 0 {
		return alt
	}
	alt, _ := pr.subsets(next.list)
	return alt
}

// predictLLUncached runs ANTLR's full-context prediction of decision d from
// the current token, with the parser's call stack as the outer context.
func (p *PlanGalopParser) predictLLUncached(d int) int {
	pr := &p.pred
	pr.full = true
	pr.pool.reset(false)
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	pr.prec = p.prec
	pr.startLL(d, p.stack, cur)
	for offset := 0; ; {
		p.peekAt(p.pos + offset)
		t := p.la(offset + 1)
		switch alt := pr.stepLL(cur, t, intermediate, next); {
		case alt < 0:
			p.llBad = true
			p.noViableAlt(d)
		case alt > 0:
			return int(alt)
		}
		cur, next = next, cur
		if t != -1 {
			offset++
		}
	}
}

// PlanGalopFullCache is the full-context prediction cache. For a
// decision and a call stack, ANTLR's full-context prediction depends only on
// the tokens ahead, so it is cached like the SLL DFA, as a DFA per (decision,
// stack): states are configuration sets whose contexts live in the
// cache's pool, which is never reset, so they keep their meaning.
// Finding a cached start state takes a read lock and walking cached edges no
// lock; new states are computed under the write lock. Past PlanGalopFullMaxStates
// states or PlanGalopFullMaxContexts contexts the cache stops growing, and
// prediction it cannot answer runs uncached. (Starting over instead thrashes
// when the predictions in use outgrow it, and building cached states costs
// more than predicting uncached.)
type PlanGalopFullCache struct {
	mu     sync.RWMutex
	full   atomic.Bool
	starts map[string]*PlanGalopDFAState
	states map[string]*PlanGalopDFAState
	pr     PlanGalopPredictor
	key    []byte // scratch for state keys
}

// PlanGalopFullMaxStates and PlanGalopFullMaxContexts bound the cache.
const (
	PlanGalopFullMaxStates   = 1 << 15
	PlanGalopFullMaxContexts = 1 << 20
)

// PlanGalopFull is the process's full-context prediction cache.
var PlanGalopFull = func() *PlanGalopFullCache {
	g := &PlanGalopFullCache{starts: map[string]*PlanGalopDFAState{}, states: map[string]*PlanGalopDFAState{}}
	g.pr.pool.reset(false)
	g.pr.full = true
	return g
}()

// isFull says whether g has stopped growing, and records it in g.full; call
// it under the write lock.
func (g *PlanGalopFullCache) isFull() bool {
	if len(g.states) >= PlanGalopFullMaxStates || len(g.pr.pool.kind) >= PlanGalopFullMaxContexts {
		g.full.Store(true)
	}
	return g.full.Load()
}

// start returns the start state of decision d under the call stack whose key
// (the decision, then the stack) is key, or nil when it is not cached and
// the cache is full.
func (g *PlanGalopFullCache) start(d int, stack []int32, key []byte, prec int32) *PlanGalopDFAState {
	g.mu.RLock()
	st, ok := g.starts[string(key)]
	g.mu.RUnlock()
	if ok || g.full.Load() {
		return st
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if st, ok := g.starts[string(key)]; ok {
		return st
	}
	if g.isFull() {
		return nil
	}
	g.pr.prec = prec
	g.pr.startLL(d, stack, &g.pr.sets[0])
	st = PlanGalopInternState(g.states, &g.pr, &g.key, -1, &g.pr.sets[0], PlanGalopMaxTokenType+2)
	g.starts[string(key)] = st
	return st
}

// next computes and caches the edge of from on token t; nil when the cache
// is full.
func (g *PlanGalopFullCache) next(from *PlanGalopDFAState, t int32) *PlanGalopDFAState {
	if g.full.Load() {
		return from.edges[t+1].Load()
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if st := from.edges[t+1].Load(); st != nil {
		return st
	}
	if g.isFull() {
		return nil
	}
	pr := &g.pr
	cur, intermediate, next := &pr.sets[0], &pr.sets[1], &pr.sets[2]
	cur.reset()
	for _, c := range from.configs {
		cur.add(c, &pr.pool)
	}
	var st *PlanGalopDFAState
	switch alt := pr.stepLL(cur, t, intermediate, next); {
	case alt < 0:
		st = PlanGalopDFAError
	case alt > 0:
		st = &PlanGalopDFAState{alt: alt}
	default:
		st = PlanGalopInternState(g.states, pr, &g.key, -1, next, PlanGalopMaxTokenType+2)
	}
	from.edges[t+1].Store(st)
	return st
}

// predictLL runs ANTLR's full-context prediction of decision d from the
// current token, with the parser's call stack as the outer context, through
// the cache when it can.
func (p *PlanGalopParser) predictLL(d int) int {
	p.stats.FullContext++
	key := binary.LittleEndian.AppendUint32(p.llKey[:0], uint32(d))
	for _, ret := range p.stack {
		key = binary.LittleEndian.AppendUint32(key, uint32(ret))
	}
	if PlanGalopDecisionPrecedence[d] {
		// A left-recursive rule's decision starts from its precedence.
		key = binary.LittleEndian.AppendUint32(key, uint32(p.prec)|1<<31)
	}
	p.llKey = key
	st := PlanGalopFull.start(d, p.stack, key, p.prec)
	for i := 1; st != nil; i++ {
		p.peekAt(p.pos + i - 1)
		t := p.la(i)
		if t < -1 || int(t)+1 >= len(st.edges) {
			break
		}
		next := st.edges[t+1].Load()
		if next == nil {
			if next = PlanGalopFull.next(st, t); next == nil {
				break
			}
		}
		switch {
		case next == PlanGalopDFAError:
			p.llBad = true
			p.noViableAlt(d)
		case next.alt > 0:
			return int(next.alt)
		}
		st = next
	}
	return p.predictLLUncached(d)
}

// Kinds of decisions in PlanGalopDecisionKind, and of Sync in PlanGalopStateSync.
const (
	PlanGalopDecisionAlt    = 0
	PlanGalopDecisionOpt    = 1
	PlanGalopDecisionStar   = 2
	PlanGalopDecisionPlus   = 3
	PlanGalopSyncBlockStart = 1
	PlanGalopSyncLoopBack   = 2
)

// PlanGalopExpected is a set of token types, EOF included, being collected for an
// error message.
type PlanGalopExpected struct {
	in []bool // indexed by token type + 1
}

// PlanGalopNewExpected is an empty PlanGalopExpected.
func PlanGalopNewExpected() *PlanGalopExpected {
	return &PlanGalopExpected{in: make([]bool, PlanGalopMaxTokenType+2)}
}

func (x *PlanGalopExpected) add(set []int32) {
	for i := 0; i < len(set); i += 2 {
		for t := set[i]; t <= set[i+1]; t++ {
			x.in[t+1] = true
		}
	}
}

// has reports whether t is in the set; a type outside the vocabulary never is.
func (x *PlanGalopExpected) has(t int32) bool { return t+1 >= 0 && int(t+1) < len(x.in) && x.in[t+1] }

// String renders the set as ANTLR's IntervalSet.StringVerbose: one name, or
// names in type order between braces.
func (x *PlanGalopExpected) String() string {
	var names []string
	for i, ok := range x.in {
		if !ok {
			continue
		}
		if i == 0 {
			names = append(names, "<EOF>")
		} else {
			names = append(names, PlanGalopTokenDisplay[i-1])
		}
	}
	if len(names) == 1 {
		return names[0]
	}
	return "{" + strings.Join(names, ", ") + "}"
}

// PlanGalopEmuError is an error ANTLR reports: its message, at token at. A
// prediction that found no viable alternative (noViable) started at token
// start, which ANTLR's NoViableAltException records.
type PlanGalopEmuError struct {
	at       int
	msg      string
	noViable bool
	start    int
}

// PlanGalopEmu replays ANTLR's parse of the parser's tokens; see errorsSource.
// fallbacks are the alternatives its predictions fell back on.
type PlanGalopEmu struct {
	p         *PlanGalopParser
	pending   *PlanGalopEmuError
	sll       PlanGalopSLLFailure
	fallbacks []PlanGalopFallback
	// precs are the precedences of the rule calls on the parser's stack;
	// a grammar without left recursion keeps none (all are 0).
	precs []int32
}

// PlanGalopFallback is a prediction of decision d at token pos that found no
// viable alternative, where ANTLR predicts alt instead of failing (see
// sllFailure).
type PlanGalopFallback struct {
	d, pos, prec, alt int32
}

// deadEnd is a prediction of decision d that found no viable alternative at
// the current token: a syntax error, unless antlrError found that ANTLR falls
// back on an alternative there.
func (p *PlanGalopParser) deadEnd(d int) int {
	for _, f := range p.fallbacks {
		if int(f.d) == d && int(f.pos) == p.pos && (!PlanGalopDecisionPrecedence[d] || f.prec == p.prec) {
			return int(f.alt)
		}
	}
	p.noViableAlt(d)
	return 0
}

// antlrError replaces err, the final parse's syntax error, with the first
// error ANTLR reports parsing the same tokens from rule's start state. The
// replay predicts over the tokens alone, never over bracketed groups. The
// parser's position is left where the failed parse left it.
//
// ANTLR may report no error at all: where its prediction finds no viable
// alternative after one had left the decision's rule, it takes that one and
// parses on, and an entry rule that does not end with EOF can then stop
// early, without error. antlrError then returns nil and leaves the
// alternatives ANTLR fell back on in p.fallbacks, for deadEnd to take.
func (p *PlanGalopParser) antlrError(start int32, err error) error {
	// Most inputs that reach here have a syntax error and store nothing, so
	// the key is built only once the cache holds something.
	if PlanGalopFallbackCount.Load() > 0 {
		if key := PlanGalopFallbackKey(start, p.types); key != "" {
			if f, ok := PlanGalopFallbackCache.Load(key); ok {
				p.fallbacks = f.([]PlanGalopFallback)
				return nil
			}
		}
	}
	pos, ll, group := p.pos, p.ll, p.group
	defer func() { p.pos, p.ll, p.group = pos, ll, group }()
	p.ll, p.group, p.fallbacks = true, false, nil
	// Conflicts the repair checked need no full-context prediction again.
	if len(p.rp.recs) > 0 {
		p.rp.indexRecs()
		defer func() { p.rp.byPos = nil }()
	}
	e := PlanGalopEmu{p: p}
	switch found := e.run(start); {
	case found != nil:
		return p.syntaxErrorAt(found.at, found.msg)
	case len(e.fallbacks) > 0:
		p.fallbacks = e.fallbacks
		if key := PlanGalopFallbackKey(start, p.types); key != "" && PlanGalopFallbackCount.Add(1) <= PlanGalopFallbackMax {
			PlanGalopFallbackCache.Store(key, e.fallbacks)
		}
		return nil
	}
	return err
}

// PlanGalopFallbackCache holds, by entry rule and token types, the alternatives
// antlrError found ANTLR's prediction falling back on where the parse reports
// no error. The replay reads token types alone, so its answer is the same for
// any input with the same types, as an SLL DFA state is; the cache spares
// inputs of one shape replaying it again. It keeps at most PlanGalopFallbackMax
// answers, for inputs of at most PlanGalopFallbackMaxTokens tokens, and never
// forgets one.
var (
	PlanGalopFallbackCache     sync.Map
	PlanGalopFallbackCount     atomic.Int64
	PlanGalopFallbackMax       = int64(1 << 12)
	PlanGalopFallbackMaxTokens = 1 << 10
)

// PlanGalopFallbackKey is the cache key of a replay from start over types, or ""
// for an input too long to cache.
func PlanGalopFallbackKey(start int32, types []int32) string {
	if len(types) > PlanGalopFallbackMaxTokens {
		return ""
	}
	k := binary.LittleEndian.AppendUint32(make([]byte, 0, 4*len(types)+4), uint32(start))
	for _, t := range types {
		k = binary.LittleEndian.AppendUint32(k, uint32(t))
	}
	return string(k)
}

// expected is ANTLR's getExpectedTokens at state s with the parser's stack:
// what can follow s, through the rules on the stack while their ends can be
// reached, and EOF past the outermost.
func (e *PlanGalopEmu) expected(s int32) *PlanGalopExpected {
	x := PlanGalopNewExpected()
	x.add(PlanGalopTokenSets[PlanGalopStateNext[s]])
	reaches := PlanGalopStateReachesEnd[s]
	for i := len(e.p.stack) - 1; i >= 0 && reaches; i-- {
		f := e.p.stack[i]
		x.add(PlanGalopTokenSets[PlanGalopStateNext[f]])
		reaches = PlanGalopStateReachesEnd[f]
	}
	if reaches {
		x.in[0] = true
	}
	return x
}

// PlanGalopQuote is ANTLR's escapeWSAndQuote.
func PlanGalopQuote(s string) string {
	s = strings.ReplaceAll(s, "\t", "\\t")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	return "'" + s + "'"
}

// report is ANTLR's "<what> input <token> expecting <set>" at the current token.
func (e *PlanGalopEmu) report(what string, exp *PlanGalopExpected) *PlanGalopEmuError {
	pos := e.p.pos
	return &PlanGalopEmuError{at: pos, msg: what + " input " + PlanGalopQuote(e.p.tokenDisplay(pos)) + " expecting " + exp.String()}
}

func (e *PlanGalopEmu) noViable(start, off int) *PlanGalopEmuError {
	input := "<EOF>"
	if e.p.types[start] != antlr.TokenEOF {
		input = e.p.inputText(start, off)
	}
	return &PlanGalopEmuError{at: off, msg: "no viable alternative at input " + PlanGalopQuote(input), noViable: true, start: start}
}

// How ANTLR's RecoverInline and Sync recover (see inlineFix and syncFix):
// the token fits (Sync only), the current token is deleted, the missing
// token is inserted (RecoverInline only), the input is skipped to what can
// follow (Sync at a loop back), or a mismatch is left pending.
const (
	PlanGalopFixNone = iota
	PlanGalopFixDelete
	PlanGalopFixInsert
	PlanGalopFixSkip
	PlanGalopFixMismatch
)

// inlineFix is how ANTLR's RecoverInline recovers at match state s, whose
// transition leads to next, with exp, the tokens expected at s, and the
// error it reports or, for a mismatch, sets. The first-error replay and the
// recovering parse both decide with it.
func (e *PlanGalopEmu) inlineFix(s, next int32) (fix int, exp *PlanGalopExpected, err *PlanGalopEmuError) {
	exp = e.expected(s)
	switch {
	case exp.has(e.la2()):
		return PlanGalopFixDelete, exp, e.report("extraneous", exp)
	case e.expected(next).has(e.p.la(1)):
		pos := e.p.pos
		return PlanGalopFixInsert, exp, &PlanGalopEmuError{at: pos, msg: "missing " + exp.String() + " at " + PlanGalopQuote(e.p.tokenDisplay(pos))}
	}
	return PlanGalopFixMismatch, exp, e.report("mismatched", exp)
}

// syncFix is how ANTLR's Sync recovers at s, a block start or a loop back
// (outside error recovery mode), like inlineFix.
func (e *PlanGalopEmu) syncFix(s int32, blockStart bool) (fix int, exp *PlanGalopExpected, err *PlanGalopEmuError) {
	if PlanGalopStateReachesEnd[s] || PlanGalopInSet(PlanGalopTokenSets[PlanGalopStateNext[s]], e.p.la(1)) {
		return PlanGalopFixNone, nil, nil
	}
	exp = e.expected(s)
	switch {
	case !blockStart:
		return PlanGalopFixSkip, exp, e.report("extraneous", exp)
	case exp.has(e.la2()):
		return PlanGalopFixDelete, exp, e.report("extraneous", exp)
	}
	return PlanGalopFixMismatch, exp, e.report("mismatched", exp)
}

// recoverInline is ANTLR's RecoverInline at match state s, whose transition
// leads to next: an error it reports is returned, a mismatch it only sets
// becomes pending.
func (e *PlanGalopEmu) recoverInline(s, next int32) *PlanGalopEmuError {
	fix, _, err := e.inlineFix(s, next)
	if fix == PlanGalopFixMismatch {
		e.pending = err
		return nil
	}
	return err
}

// sync is ANTLR's Sync at s, of a block start or a loop back, followed by the
// generated code's error check if check is set: an error it reports is
// returned; a mismatch at a block start becomes pending.
func (e *PlanGalopEmu) sync(s int32, blockStart, check bool) *PlanGalopEmuError {
	switch fix, _, err := e.syncFix(s, blockStart); fix {
	case PlanGalopFixNone:
	case PlanGalopFixMismatch:
		e.pending = err
	default:
		return err
	}
	if check {
		return e.pending
	}
	return nil
}

// la2 is LA(2), which makes ANTLR's token stream read the token after the
// current one.
func (e *PlanGalopEmu) la2() int32 {
	e.p.peekAt(e.p.pos + 1)
	return e.p.la(2)
}

// ll1Alt is the alternative of decision d whose lookahead has LA(1), or 0.
func (e *PlanGalopEmu) ll1Alt(d int) int {
	t := e.p.la(1)
	for i := PlanGalopAltLookStart[d]; i < PlanGalopAltLookStart[d+1]; i++ {
		if PlanGalopInSet(PlanGalopTokenSets[PlanGalopAltLook[i]], t) {
			return int(i-PlanGalopAltLookStart[d]) + 1
		}
	}
	return 0
}

func (e *PlanGalopEmu) consume() {
	if e.p.types[e.p.pos] != antlr.TokenEOF {
		e.p.pos++
	}
}

// run replays ANTLR from state s, a rule's start, and returns the first
// error it reports, or nil.
func (e *PlanGalopEmu) run(s int32) *PlanGalopEmuError {
	p := e.p
	p.pos = 0
	p.stack = p.stack[:0]
	e.precs = e.precs[:0]
	// back says the walk just left a loop back, which synced already: a
	// loop's next iteration does not sync at its start.
	back := false
	for {
		fromBack := back
		back = false
		if PlanGalopStateIsStop[s] {
			// The end of a rule function checks for an error.
			if e.pending != nil {
				return e.pending
			}
			if len(p.stack) == 0 {
				return nil
			}
			s = p.stack[len(p.stack)-1]
			p.stack = p.stack[:len(p.stack)-1]
			if PlanGalopMaxPrec > 0 {
				e.precs = e.precs[:len(e.precs)-1]
			}
			continue
		}
		if d := int(PlanGalopStateDecision[s]); d >= 0 {
			// ANTLR matches the alternatives of a set decision as one set.
			if after := PlanGalopDecisionSetAfter[d]; after >= 0 {
				if e.ll1Alt(d) > 0 {
					e.consume()
				} else if err := e.recoverInline(s, after); err != nil {
					return err
				}
				s = after
				continue
			}
			alt, err := e.decide(d, s, fromBack)
			if err != nil {
				return err
			}
			back = PlanGalopDecisionKind[d] == PlanGalopDecisionPlus && alt == int(PlanGalopDecisionLoopAlt[d])
			s = PlanGalopTransTarget[PlanGalopTransStart[s]+int32(alt)-1]
			continue
		}
		switch PlanGalopStateSync[s] {
		case PlanGalopSyncLoopBack:
			if err := e.sync(s, false, true); err != nil {
				return err
			}
			back = true
		case PlanGalopSyncBlockStart:
			if !fromBack {
				if err := e.sync(s, true, true); err != nil {
					return err
				}
			}
		}
		i := PlanGalopTransStart[s]
		t := PlanGalopTransTarget[i]
		switch PlanGalopTransKind[i] {
		case PlanGalopKindEpsilon:
		case PlanGalopKindRule:
			p.stack = append(p.stack, PlanGalopTransArg[i])
			if PlanGalopMaxPrec > 0 {
				e.precs = append(e.precs, PlanGalopStateCallPrec[s])
			}
		case PlanGalopKindPrec:
			// The generated code checks precpred and fails the rule.
			if level := PlanGalopTransArg[i]; level < e.prec() {
				return e.failedPredicate(s, level)
			}
		default:
			if PlanGalopMatches(i, p.la(1)) {
				e.consume()
			} else if err := e.recoverInline(s, t); err != nil {
				return err
			}
			// The generated code checks for an error after a token match,
			// not after a set match.
			if PlanGalopTransKind[i] == PlanGalopKindAtom && e.pending != nil {
				return e.pending
			}
		}
		s = t
	}
}

// prec is the precedence of the innermost rule call, 0 in the start rule.
func (e *PlanGalopEmu) prec() int32 {
	if len(e.precs) == 0 {
		return 0
	}
	return e.precs[len(e.precs)-1]
}

// failedPredicate is the error ANTLR reports when the precedence predicate
// of level at state s fails, in the Go target's words.
func (e *PlanGalopEmu) failedPredicate(s int32, level int32) *PlanGalopEmuError {
	if e.pending != nil {
		return e.pending
	}
	return &PlanGalopEmuError{at: e.p.pos, msg: "rule " + PlanGalopRuleName[PlanGalopStateRule[s]] + " failed predicate: {p.Precpred(p.GetParserRuleContext(), " + PlanGalopItoa(level) + ")}?"}
}

// PlanGalopItoa formats n, which is not negative, in decimal; it saves both flavors
// importing strconv for one message.
func PlanGalopItoa(n int32) string {
	if n < 10 {
		return string(rune('0' + n))
	}
	return PlanGalopItoa(n/10) + string(rune('0'+n%10))
}

// decide makes decision d at state s as ANTLR's generated code does; fromBack
// says the walk came from the loop back of a star loop, which synced already.
func (e *PlanGalopEmu) decide(d int, s int32, fromBack bool) (int, *PlanGalopEmuError) {
	pos := e.p.pos
	ll1 := PlanGalopDecisionLL1[d]
	// A token an alternative accepts passes Sync too: an LL(1) answer with no
	// error pending needs no Sync.
	if ll1 && e.pending == nil {
		if alt := e.ll1Alt(d); alt > 0 {
			return alt, nil
		}
	}
	var err *PlanGalopEmuError
	switch PlanGalopDecisionKind[d] {
	case PlanGalopDecisionAlt:
		err = e.sync(s, true, true)
	case PlanGalopDecisionOpt:
		// Adaptive prediction follows Sync with no error check.
		err = e.sync(s, true, ll1)
	case PlanGalopDecisionStar:
		if !fromBack {
			err = e.sync(s, true, true)
		}
	case PlanGalopDecisionPlus:
		err = e.sync(s, false, ll1)
	}
	switch {
	case err != nil:
		return 0, err
	case !ll1:
		return e.predict(d)
	}
	if alt := e.ll1Alt(d); alt > 0 {
		return alt, nil
	}
	// An LL(1) choice fails; an optional block or a loop exits.
	if PlanGalopDecisionKind[d] == PlanGalopDecisionAlt {
		return 0, e.noViable(pos, pos)
	}
	return int(PlanGalopAltLookStart[d+1] - PlanGalopAltLookStart[d]), nil
}

// predict is ANTLR's AdaptivePredict for decision d, which sets the parser's
// error to its outcome: a failure is returned, a success clears any pending
// error.
func (e *PlanGalopEmu) predict(d int) (int, *PlanGalopEmuError) {
	p := e.p
	pos := p.pos
	p.llBad = false
	p.prec = e.prec()
	alt, ok := func() (alt int, ok bool) {
		defer func() {
			if r := recover(); r != nil {
				if _, isSE := r.(*PlanGalopSyntaxError); !isSE {
					panic(r)
				}
				alt, ok = 0, false
			}
		}()
		return p.adaptivePredict(d), true
	}()
	p.pos = pos
	e.sll.note(d, pos, e.prec())
	if !ok {
		// A failed full-context stage rewinds the input before ANTLR builds
		// its error, so the error is at the decision's first token.
		if p.llBad {
			return 0, e.noViable(pos, pos)
		}
		off, fallback := e.sllFailure(d)
		if fallback == 0 {
			return 0, e.noViable(pos, off)
		}
		alt = fallback
		e.fallbacks = append(e.fallbacks, PlanGalopFallback{int32(d), int32(pos), e.prec(), int32(alt)})
	}
	e.pending = nil
	return alt, nil
}

// PlanGalopFlagConfig is an SLL configuration with ANTLR's reachesIntoOuterContext
// as a flag. Like ANTLR's counter, the flag belongs to the configuration, not
// to one path: configurations with the same state and alternative merge, and
// so do their flags, and what a configuration reaches inherits its flag.
type PlanGalopFlagConfig struct {
	state, alt, ctx int32
	left            bool
}

// PlanGalopFlagSet is a set of PlanGalopFlagConfig, one per state and alternative. dips
// is ANTLR's dipsIntoOuterContext: building the set followed a rule's end
// with no caller known.
type PlanGalopFlagSet struct {
	list []PlanGalopFlagConfig
	at   PlanGalopMap
	dips bool
}

func (s *PlanGalopFlagSet) reset() {
	s.list = s.list[:0]
	s.at.reset()
	s.dips = false
}

func (s *PlanGalopFlagSet) add(c PlanGalopFlagConfig, cp *PlanGalopCtxPool) {
	// ANTLR's Add sets dipsIntoOuterContext for any flagged configuration.
	s.dips = s.dips || c.left
	k := uint64(uint32(c.state))<<32 | uint64(uint32(c.alt))
	if i, isNew := s.at.put(k, int32(len(s.list))); !isNew {
		s.list[i].ctx = cp.merge(s.list[i].ctx, c.ctx)
		s.list[i].left = s.list[i].left || c.left
		return
	}
	s.list = append(s.list, c)
}

// key packs c as the predictor packs its configurations, with the flag in
// bit 11 of the alternative.
func (c PlanGalopFlagConfig) key() uint64 {
	alt := c.alt
	if c.left {
		alt |= 1 << 11
	}
	return PlanGalopConfig{c.state, alt, c.ctx}.key()
}

// PlanGalopSLLFailure replays SLL prediction of a failed decision.
type PlanGalopSLLFailure struct {
	pool PlanGalopCtxPool
	busy PlanGalopMap
	set  PlanGalopFlagSet // the set being built
	mid  PlanGalopFlagSet // the configurations a token reaches, before closure
	// history lists, per decision, the tokens the replay predicted it at,
	// and precs, for a decision of a left-recursive rule, the precedence of
	// each of those predictions; walked counts those whose states are built
	// already.
	history [][]int32
	precs   [][]int32
	walked  []int
	// states are the DFA states ANTLR has built, as share finds them by
	// key; starts holds each decision's start state, or -1. They and pool
	// last for the whole replay.
	states []PlanGalopFlagState
	ids    map[string]int32
	starts []int32
	key    []byte
	// Scratch for settled.
	pr   PlanGalopPredictor
	view []PlanGalopConfig
	// While a start state is built (collect), prec is the precedence the
	// decision's rule invocation was called with; the precedence filter
	// state is the predictor's (see PlanGalopPredictor).
	prec       int32
	collect    bool
	filter     bool
	rule       int32
	suppress   bool
	suppressed PlanGalopMap
	// precStarts holds the start states of left-recursive rules' decisions,
	// by decision and precedence.
	precStarts map[int64]int32
}

// PlanGalopFlagState is a DFA state of SLL prediction, with ANTLR's flags, and its
// edges by token type: the next state, or PlanGalopFlagDead or PlanGalopFlagStop.
type PlanGalopFlagState struct {
	list  []PlanGalopFlagConfig
	edges map[int32]int32
}

// No configuration survives the token (PlanGalopFlagDead), or prediction stops at
// an answer (PlanGalopFlagStop).
const (
	PlanGalopFlagDead = int32(-1)
	PlanGalopFlagStop = int32(-2)
)

// note records that the replay predicted decision d at token pos.
func (m *PlanGalopSLLFailure) note(d, pos int, prec int32) {
	if m.history == nil {
		m.history = make([][]int32, len(PlanGalopDecisionState))
		m.precs = make([][]int32, len(PlanGalopDecisionState))
		m.walked = make([]int, len(PlanGalopDecisionState))
		m.starts = make([]int32, len(PlanGalopDecisionState))
		for i := range m.starts {
			m.starts[i] = -1
		}
		m.ids = map[string]int32{}
		m.pool.reset(true)
	}
	m.history[d] = append(m.history[d], int32(pos))
	if PlanGalopDecisionPrecedence[d] {
		m.precs[d] = append(m.precs[d], prec)
	}
}

// closure is the predictor's closure with ANTLR's flags; depth is as there.
func (m *PlanGalopSLLFailure) closure(c PlanGalopFlagConfig, out *PlanGalopFlagSet, depth int32) {
	if _, isNew := m.busy.put(m.busyKey(c, depth), 0); !isNew {
		return
	}
	cp := &m.pool
	s := c.state
	if PlanGalopStateIsStop[s] {
		// In ANTLR's order (closureCheckingStopState): the empty return,
		// which sorts last, at once; the others from a stack, last first.
		// Past the rule's end with no caller known, the configuration keeps
		// its whole context, as in ANTLR.
		from, n := cp.start[c.ctx], cp.length[c.ctx]
		if n > 0 && cp.rets[from+n-1] == PlanGalopEmptyReturn {
			m.follow(c, out, depth-1)
			n--
		}
		for i := n - 1; i >= 0; i-- {
			m.closure(PlanGalopFlagConfig{cp.rets[from+i], c.alt, cp.parents[from+i], c.left}, out, depth-1)
		}
		return
	}
	// Within a rule the predictor's precomputed closure applies: the flag only
	// changes at a rule's end.
	for i := PlanGalopClosStart[s]; i < PlanGalopClosStart[s+1]; i++ {
		t := PlanGalopClosState[i]
		switch PlanGalopClosKind[i] {
		case 0:
			m.added(out, PlanGalopFlagConfig{t, c.alt, c.ctx, c.left})
		case 1:
			m.closure(PlanGalopFlagConfig{t, c.alt, cp.singleton(c.ctx, PlanGalopClosArg[i]), c.left}, out, PlanGalopDeeper(depth))
		case 3:
			// A precedence predicate, as in the predictor's closure.
			if !m.collect || depth != 0 || PlanGalopClosArg[i] >= m.prec {
				m.closure(PlanGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
			}
		case 4:
			m.loopEntry(PlanGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
		default:
			m.closure(PlanGalopFlagConfig{t, c.alt, c.ctx, c.left}, out, depth)
		}
	}
}

// loopEntry is the predictor's loopEntry with ANTLR's flags.
func (m *PlanGalopSLLFailure) loopEntry(c PlanGalopFlagConfig, out *PlanGalopFlagSet, depth int32) {
	if _, isNew := m.busy.put(m.busyKey(c, depth)|1<<62, 0); !isNew {
		return
	}
	for i := PlanGalopTransStart[c.state]; i < PlanGalopTransStart[c.state+1]; i++ {
		if i == PlanGalopTransStart[c.state] && m.pool.canDrop(c.state, c.ctx) {
			continue
		}
		m.closure(PlanGalopFlagConfig{PlanGalopTransTarget[i], c.alt, c.ctx, c.left}, out, depth)
	}
}

// busyKey and added are the predictor's, for flagged configurations.
func (m *PlanGalopSLLFailure) busyKey(c PlanGalopFlagConfig, depth int32) uint64 {
	key := c.key()
	if m.suppress {
		key |= 1 << 63
	}
	if m.collect && depth == 0 {
		key |= 1 << 61
	}
	return key
}

func (m *PlanGalopSLLFailure) added(out *PlanGalopFlagSet, c PlanGalopFlagConfig) {
	out.add(c, &m.pool)
	if m.suppress {
		m.suppressed.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), 0)
	}
}

// hasEmptyPath is ANTLR's PredictionContext.hasEmptyPath: context c can end
// with nothing left on the stack.
func (m *PlanGalopSLLFailure) hasEmptyPath(c int32) bool {
	cp := &m.pool
	n := cp.length[c]
	return n > 0 && cp.rets[cp.start[c]+n-1] == PlanGalopEmptyReturn
}

// follow continues c, at its rule's end with no caller known, after every
// call of the rule, as SLL prediction does, flagged as having left the rule.
// A rule nobody calls keeps c there as it is.
func (m *PlanGalopSLLFailure) follow(c PlanGalopFlagConfig, out *PlanGalopFlagSet, depth int32) {
	rule := PlanGalopStateRule[c.state]
	if PlanGalopFollowStart[rule] == PlanGalopFollowStart[rule+1] {
		m.added(out, c)
		return
	}
	for i := PlanGalopFollowStart[rule]; i < PlanGalopFollowStart[rule+1]; i++ {
		f := PlanGalopFlagConfig{PlanGalopFollowState[i], c.alt, c.ctx, true}
		// ANTLR sets dipsIntoOuterContext here only for a configuration new
		// to the closure.
		suppress := m.filter && rule == m.rule && PlanGalopFollowOuter[i] && !m.suppress
		if suppress {
			m.suppress = true
		}
		if _, seen := m.busy.get(m.busyKey(f, depth)); !seen {
			out.dips = true
		}
		m.closure(f, out, depth)
		if suppress {
			m.suppress = false
		}
	}
}

// sllFailure replays SLL prediction of decision d, which failed, from the
// current token. It returns the token where no configuration survives and
// the lowest alternative of a configuration flagged as having left the
// decision's rule by then, or one at a rule's end with nothing left on its
// stack (0 for none): ANTLR predicts that alternative instead of failing.
//
// The flags depend on the DFA states ANTLR already holds (see share), so the
// replay first builds the states of this parse's earlier predictions of d
// that it has not built yet, in order.
func (e *PlanGalopEmu) sllFailure(d int) (offending int, alt int) {
	m := &e.sll
	h := m.history[d]
	for i := m.walked[d]; i < len(h)-1; i++ {
		prec := int32(0)
		if PlanGalopDecisionPrecedence[d] {
			prec = m.precs[d][i]
		}
		m.walk(e.p.types, d, int(h[i]), prec)
	}
	m.walked[d] = len(h)
	offending, alt, _ = m.walk(e.p.types, d, e.p.pos, e.prec())
	return offending, alt
}

// walk runs SLL prediction of decision d from token from over the DFA states
// built so far, building the missing ones as ANTLR does. It reports whether
// prediction failed, and if so the token where it failed and the alternative
// ANTLR falls back on (see sllFailure).
func (m *PlanGalopSLLFailure) walk(types []int32, d int, from int, prec int32) (offending int, alt int, failed bool) {
	st := m.start(d, prec)
	for pos := from; ; pos++ {
		t := types[pos]
		next, ok := m.states[st].edges[t]
		if !ok && t != antlr.TokenEOF {
			next = m.target(d, st, t)
			m.states[st].edges[t] = next
		}
		// A prediction that reads EOF stops there.
		if next == PlanGalopFlagDead || t == antlr.TokenEOF {
			best := int32(0)
			for _, c := range m.states[st].list {
				done := PlanGalopStateIsStop[c.state] && m.hasEmptyPath(c.ctx)
				if (c.left || done) && (best == 0 || c.alt < best) {
					best = c.alt
				}
			}
			return pos, int(best), true
		}
		if next == PlanGalopFlagStop {
			return pos, 0, false
		}
		st = next
	}
}

// start returns decision d's start state, building it once, as ANTLR does:
// for a decision of a left-recursive rule, once per precedence its rule is
// called with.
func (m *PlanGalopSLLFailure) start(d int, prec int32) int32 {
	key := int64(d)<<32 | int64(uint32(prec))
	if !PlanGalopDecisionPrecedence[d] {
		if m.starts[d] >= 0 {
			return m.starts[d]
		}
	} else if st, ok := m.precStarts[key]; ok {
		return st
	}
	m.set.reset()
	m.busy.reset()
	s := PlanGalopDecisionState[d]
	m.prec, m.collect = prec, true
	m.filter, m.rule = PlanGalopDecisionLoopEntry[d], PlanGalopStateRule[s]
	m.suppressed.reset()
	for i := PlanGalopTransStart[s]; i < PlanGalopTransStart[s+1]; i++ {
		m.closure(PlanGalopFlagConfig{PlanGalopTransTarget[i], i - PlanGalopTransStart[s] + 1, 0, false}, &m.set, 0)
	}
	m.collect = false
	if m.filter {
		m.precedenceFilter(&m.set)
		m.filter = false
	}
	st := m.share(d, &m.set)
	if PlanGalopDecisionPrecedence[d] {
		if m.precStarts == nil {
			m.precStarts = map[int64]int32{}
		}
		m.precStarts[key] = st
	} else {
		m.starts[d] = st
	}
	return st
}

// precedenceFilter is the predictor's, for flagged configurations; a
// configuration's flags do not take part.
func (m *PlanGalopSLLFailure) precedenceFilter(set *PlanGalopFlagSet) {
	alt1 := map[int32]int32{}
	for _, c := range set.list {
		if c.alt == 1 {
			alt1[c.state] = c.ctx
		}
	}
	n := 0
	for _, c := range set.list {
		if c.alt != 1 {
			_, spared := m.suppressed.get(uint64(uint32(c.state))<<32 | uint64(uint32(c.alt)))
			if ctx, ok := alt1[c.state]; ok && ctx == c.ctx && !spared {
				continue
			}
		}
		set.list[n] = c
		n++
	}
	set.list = set.list[:n]
	set.at.reset()
	for i, c := range set.list {
		set.at.put(uint64(uint32(c.state))<<32|uint64(uint32(c.alt)), int32(i))
	}
}

// target computes the edge of state st on token t, as ANTLR's
// computeTargetState and computeReachSet do: what t reaches is merged, then
// closed.
func (m *PlanGalopSLLFailure) target(d int, st int32, t int32) int32 {
	m.mid.reset()
	for _, c := range m.states[st].list {
		for i := PlanGalopTransStart[c.state]; i < PlanGalopTransStart[c.state+1]; i++ {
			k := PlanGalopTransKind[i]
			if (k == PlanGalopKindAtom || k == PlanGalopKindSet) && PlanGalopMatches(i, t) {
				m.mid.add(PlanGalopFlagConfig{PlanGalopTransTarget[i], c.alt, c.ctx, c.left}, &m.pool)
			}
		}
	}
	m.set.reset()
	m.busy.reset()
	for _, c := range m.mid.list {
		m.closure(c, &m.set, 0)
	}
	switch {
	case len(m.set.list) == 0:
		return PlanGalopFlagDead
	case m.settled(m.set.list):
		return PlanGalopFlagStop
	}
	return m.share(d, &m.set)
}

// settled reports whether SLL prediction stops at a set, as PlanGalopDFAGen.next does:
// one alternative is left, or an SLL conflict.
func (m *PlanGalopSLLFailure) settled(list []PlanGalopFlagConfig) bool {
	v := m.view[:0]
	for _, c := range list {
		v = append(v, PlanGalopConfig{c.state, c.alt, c.ctx})
	}
	m.view = v
	return PlanGalopUniqueAlt(v) != 0 || m.pr.conflict(v)
}

// share returns ANTLR's DFA state of decision d for set: a state built
// before for an equal set, with that state's flags, or a new state with
// set's. ANTLR's states are equal when they hold the same configurations in
// the same order (unlike PlanGalopInternState, order counts) and agree on
// dipsIntoOuterContext; the flags do not count.
func (m *PlanGalopSLLFailure) share(d int, set *PlanGalopFlagSet) int32 {
	k := binary.LittleEndian.AppendUint32(m.key[:0], uint32(d))
	for _, c := range set.list {
		k = binary.LittleEndian.AppendUint32(k, uint32(c.state))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.alt))
		k = binary.LittleEndian.AppendUint32(k, uint32(c.ctx))
	}
	if set.dips {
		k = append(k, 1)
	}
	m.key = k
	if id, ok := m.ids[string(k)]; ok {
		return id
	}
	id := int32(len(m.states))
	m.states = append(m.states, PlanGalopFlagState{list: slices.Clone(set.list), edges: map[int32]int32{}})
	m.ids[string(k)] = id
	return id
}

// tokenDisplay is token i's text as ANTLR's error messages show it.
func (p *PlanGalopParser) tokenDisplay(i int) string {
	t := p.toks[i]
	if s := t.GetText(); s != "" {
		return s
	}
	if t.GetTokenType() == antlr.TokenEOF {
		return "<EOF>"
	}
	return fmt.Sprintf("<%d>", t.GetTokenType())
}

// inputText is the text of tokens start to stop, with the off-channel tokens
// between them, as ANTLR's token stream gives it.
func (p *PlanGalopParser) inputText(start, stop int) string {
	return p.input.GetTextFromTokens(p.toks[start], p.toks[stop])
}

// syntaxErrorAt is a syntax error with message msg at token i.
func (p *PlanGalopParser) syntaxErrorAt(i int, msg string) error {
	return &PlanGalopSyntaxError{p.toks[i], msg}
}

