var PlanGalopLiteralNames = []string{
	"", "'('", "')'", "'['", "','", "']'", "'{'", "'}'", "'<'", "'<='", "'>'", "'>='", "'=='", "'!='", "", "", "", "", "", "", "", "", "", "",
	"", "", "", "", "", "'=~'", "'!~'", "'='", "'+'", "'-'", "'*'", "'/'", "'%'", "'**'", "'<<'", "'>>'", "'&'", "'|'", "'^'", "", "", "", "", "'~'",
	"", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "", "",
	"'$meta'",
}

// PlanGalopRecovery is the state of a recovering parse: ANTLR's parser state
// (GetState, the error strategy's fields) and the contexts of the rules
// being parsed.
type PlanGalopRecovery struct {
	e PlanGalopEmu
	// state is ANTLR's GetState(): the ATN state of the generated code's
	// last SetState.
	state int32
	// The default error strategy's errorRecoveryMode, lastErrorIndex and
	// lastErrorStates.
	recovering bool
	lastIndex  int
	lastStates []int32
	// ctxs are the contexts of the rules being parsed, innermost last; the
	// parser's stack holds their return states, as in the replay.
	ctxs []antlr.ParserRuleContext
	// root is the entry rule's context, once the rule is done.
	root antlr.ParserRuleContext
	// conjured are the tokens single-token insertion made up: a token
	// reference past the parser's tokens is one of them.
	conjured []antlr.Token
	// exc is the pending error's exception (see pend).
	exc antlr.RecognitionException
	// errors counts the errors reported.
	errors int
}

// recoverParse parses from the first token as rule (its index) with ANTLR's
// error recovery; see antlrRecoverySource. It predicts in LL mode over the
// tokens alone, as antlrError's replay does. It returns the entry rule's
// context and the number of syntax errors reported, and leaves the token
// stream and the embedded parser as ANTLR's parse leaves them.
func (p *PlanGalopParser) recoverParse(rule int) (antlr.ParserRuleContext, int) {
	p.ll, p.group, p.peek = true, false, 0
	r := &PlanGalopRecovery{e: PlanGalopEmu{p: p}, lastIndex: -1}
	r.parse(rule)
	p.flushLexErrors(r.read())
	p.input.Seek(p.toks[p.pos].GetTokenIndex())
	p.SetParserRuleContext(nil)
	p.SetState(-1)
	return r.root, r.errors
}

// top is the context of the rule being parsed.
func (r *PlanGalopRecovery) top() antlr.ParserRuleContext { return r.ctxs[len(r.ctxs)-1] }

// enter starts rule, called from state invoking: ANTLR's EnterRule, which
// starts the rule's context at the current token and adds it to its
// parent's children. A rule with one labeled alternative enters it at once.
func (r *PlanGalopRecovery) enter(rule, invoking int32) {
	p := r.e.p
	var parent antlr.ParserRuleContext
	if len(r.ctxs) > 0 {
		parent = r.top()
	}
	ctx := p.newContext(rule, parent, int(invoking))
	ctx.SetStart(p.toks[p.pos])
	// A left-recursive rule's context joins its parent when the rule ends
	// (EnterRecursionRule, UnrollRecursionContexts).
	if parent != nil && !PlanGalopRuleRecursive[rule] {
		parent.AddChild(ctx)
	}
	r.ctxs = append(r.ctxs, ctx)
	if alt := PlanGalopRuleAlt[rule]; alt != 0 {
		r.enterOuterAlt(alt)
	}
}

// recursionStart starts an iteration of a left-recursive rule's loop with
// op alternative alt (0 for an unlabeled one), as ANTLR's generated code
// does: a new context of the rule, or of alt's label, made from the rule's
// parent and invoking state, whose label left (if not 0) gets the rule's
// context so far; then PushNewRecursionContext, which ends that context at
// the last token read, makes it the new one's first child and starts the new
// one where it started.
func (r *PlanGalopRecovery) recursionStart(alt uint8, left uint16) {
	p := r.e.p
	n := len(r.ctxs) - 1
	prev := r.ctxs[n]
	rule := int32(prev.GetRuleIndex())
	parent, _ := prev.GetParent().(antlr.ParserRuleContext)
	ctx := p.newContext(rule, parent, prev.GetInvokingState())
	if alt != 0 {
		ctx = p.newAltContext(rule, alt, ctx)
	}
	if left != 0 {
		p.setLabel(ctx, left, nil, prev)
	}
	prev.SetParent(ctx)
	prev.SetInvokingState(int(PlanGalopRuleStartState[rule]))
	prev.SetStop(p.toks[p.pos-1])
	ctx.SetStart(prev.GetStart())
	ctx.AddChild(prev)
	r.ctxs[n] = ctx
}

// enterOuterAlt makes the rule being parsed the labeled alternative alt:
// ANTLR's EnterOuterAlt with the alternative's new context, which copies the
// rule's context but none of its children and takes its place in its parent.
func (r *PlanGalopRecovery) enterOuterAlt(alt uint8) {
	n := len(r.ctxs) - 1
	old := r.ctxs[n]
	ctx := r.e.p.newAltContext(int32(old.GetRuleIndex()), alt, old)
	// A left-recursive rule's context is not among its parent's children yet.
	if parent, ok := old.GetParent().(antlr.ParserRuleContext); ok && !PlanGalopRuleRecursive[old.GetRuleIndex()] {
		parent.RemoveLastChild()
		parent.AddChild(ctx)
	}
	r.ctxs[n] = ctx
}

// exit ends the rule being parsed: ANTLR's ExitRule, which sets the
// context's stop token, then the caller's label of the result, if any. It
// returns the state the caller goes on at and -1, or for the entry rule -1
// and 0 (its context is r.root).
func (r *PlanGalopRecovery) exit() (int32, int32) {
	p := r.e.p
	n := len(r.ctxs) - 1
	ctx := r.ctxs[n]
	r.ctxs = r.ctxs[:n]
	if p.pos > 0 {
		ctx.SetStop(p.toks[p.pos-1])
	} else {
		ctx.SetStop(nil)
	}
	if n == 0 {
		r.root = ctx
		return -1, 0
	}
	if PlanGalopRuleRecursive[ctx.GetRuleIndex()] {
		r.top().AddChild(ctx)
	}
	invoking := int32(ctx.GetInvokingState())
	if l := PlanGalopStateLabel[invoking]; l != 0 {
		p.setLabel(r.top(), l, nil, ctx)
	}
	r.state = invoking
	follow := p.stack[len(p.stack)-1]
	p.stack = p.stack[:len(p.stack)-1]
	return follow, -1
}

// label stores the token tok refers to (nil for -1) in the label of the
// match at state s, if it has one, as ANTLR's generated code does.
func (r *PlanGalopRecovery) label(s int32, tok int32) {
	if l := PlanGalopStateLabel[s]; l != 0 {
		r.e.p.setLabel(r.top(), l, r.token(tok), nil)
	}
}

// token is the token ref refers to: one of the parser's, one single-token
// insertion made up, or nil for -1.
func (r *PlanGalopRecovery) token(ref int32) antlr.Token {
	p := r.e.p
	switch {
	case ref < 0:
		return nil
	case int(ref) < len(p.toks):
		return p.toks[ref]
	}
	return r.conjured[int(ref)-len(p.toks)]
}

// take adds the current token to the rule being parsed, as an error node
// when isErr (ANTLR's Consume in error recovery mode), and moves past it
// (not past EOF); it returns the token.
func (r *PlanGalopRecovery) take(isErr bool) int32 {
	p := r.e.p
	i := p.pos
	if isErr {
		r.top().AddErrorNode(p.toks[i])
	} else {
		r.top().AddTokenNode(p.toks[i])
	}
	if p.types[i] != antlr.TokenEOF {
		p.pos++
	}
	return int32(i)
}

// missing is the token ANTLR's GetMissingSymbol makes up, of the first type
// in exp, from the parser's token factory: it is added to the rule being
// parsed as an error node when add is set (ANTLR's Match adds it), and
// returned either way (a set match stores it in its label).
func (r *PlanGalopRecovery) missing(exp *PlanGalopExpected, add bool) int32 {
	p := r.e.p
	typ := exp.first()
	var text string
	switch {
	case typ == antlr.TokenEOF:
		text = "<missing EOF>"
	case typ > 0 && int(typ) < len(PlanGalopLiteralNames):
		text = "<missing " + PlanGalopLiteralNames[typ] + ">"
	default:
		text = "<missing undefined>"
	}
	at := p.toks[p.pos]
	if at.GetTokenType() == antlr.TokenEOF && p.pos > 0 {
		at = p.toks[p.pos-1]
	}
	tok := p.GetTokenFactory().Create(at.GetSource(), int(typ), text, antlr.TokenDefaultChannel, -1, -1, at.GetLine(), at.GetColumn())
	if add {
		r.top().AddErrorNode(tok)
	}
	r.conjured = append(r.conjured, tok)
	return int32(len(p.toks) + len(r.conjured) - 1)
}

// report reports err, an unwanted or a missing token, as ANTLR's
// ReportUnwantedToken and ReportMissingToken do (see notify).
func (r *PlanGalopRecovery) report(err *PlanGalopEmuError) { r.notify(err, nil) }

// pend leaves err pending, as ANTLR's SetError does, with its exception made
// now, as ANTLR makes it: an InputMisMatchException or a
// NoViableAltException that records the parser's context, state and tokens
// at this point, however much later the error is reported.
func (r *PlanGalopRecovery) pend(err *PlanGalopEmuError) {
	p := r.e.p
	r.e.pending = err
	r.syncParser()
	if err.noViable {
		r.exc = antlr.NewNoViableAltException(p, p.input, p.toks[err.start], p.toks[err.at], nil, r.top())
	} else {
		r.exc = antlr.NewInputMisMatchException(p)
	}
}

// reportPending reports the pending error at a rule's error exit as ANTLR's
// generated code does: the rule's context gets the error's exception, which
// ReportError then reports.
func (r *PlanGalopRecovery) reportPending(err *PlanGalopEmuError) {
	r.top().SetException(r.exc)
	r.notify(err, r.exc)
}

// notify passes err and its exception to the parser's error listeners, as
// ANTLR's NotifyErrorListeners does but with the galop parser as the
// recognizer (see GetExpectedTokens), unless the parser is in error recovery
// mode; and enters that mode.
func (r *PlanGalopRecovery) notify(err *PlanGalopEmuError, exc antlr.RecognitionException) {
	if r.recovering {
		return
	}
	r.recovering = true
	r.errors++
	r.syncParser()
	p := r.e.p
	p.syntaxErrors++
	p.expected = p.expectedSet(r.e.expected(r.state).types())
	tok := p.toks[err.at]
	// The token recognition errors ANTLR's parse has lexed come first.
	p.flushLexErrors(r.read())
	p.GetErrorListenerDispatch().SyntaxError(p, tok, tok.GetLine(), tok.GetColumn(), err.msg, exc)
}

// syncParser sets the embedded parser's state, context and current token to
// ANTLR's at this point of its parse, for error listeners and exceptions.
// The state is galop's number for it: galop's state machine numbers its
// states differently from ANTLR's.
func (r *PlanGalopRecovery) syncParser() {
	p := r.e.p
	p.SetState(int(r.state))
	p.SetParserRuleContext(r.top())
	p.input.Seek(p.toks[p.pos].GetTokenIndex())
}

// expectedSet is types as an ANTLR IntervalSet. ANTLR's runtime exports no
// way to fill one, so it is what ANTLR's own analysis finds can follow a
// state with one transition per type.
func (p *PlanGalopParser) expectedSet(types []int32) *antlr.IntervalSet {
	s := antlr.NewBasicState()
	end := antlr.NewBasicState()
	for _, t := range types {
		s.AddTransition(antlr.NewAtomTransition(end, int(t)), -1)
	}
	return p.GetATN().NextTokensInContext(s, nil)
}

// GetExpectedTokens is, while an error listener runs, ANTLR's
// GetExpectedTokens at that error: the tokens that can follow the parser's
// state through the rules being parsed. galop answers it from its own state
// machine (ANTLR's would need ANTLR's state numbers); outside an error
// report it is the last error's set, or empty.
func (p *PlanGalopParser) GetExpectedTokens() *antlr.IntervalSet {
	if p.expected == nil {
		return antlr.NewIntervalSet()
	}
	return p.expected
}

// GetNumberOfSyntaxErrors is the number of syntax errors the parser reported
// to its error listeners, as ANTLR's.
func (p *PlanGalopParser) GetNumberOfSyntaxErrors() int { return p.syntaxErrors }

// The bits of PlanGalopStateLabel: the label's number (as the native parser
// numbers a rule's labels, from 1; a node's Label is a uint8) and whether it
// collects a list.
const (
	PlanGalopLabelNumber = 255
	PlanGalopLabelList   = 255 + 1
)

// parse walks the ATN from the start of rule, as errorsSource's run does,
// recovering from errors as ANTLR does, and returns the root node.
func (r *PlanGalopRecovery) parse(rule int) int32 {
	e := &r.e
	p := e.p
	p.pos = 0
	p.stack = p.stack[:0]
	e.precs = e.precs[:0]
	r.enter(int32(rule), -1)
	s := PlanGalopRuleStartState[rule]
	// back says the walk just left a loop back, which synced already: a
	// loop's next iteration does not sync at its start.
	back := false
	var root int32
	for {
		fromBack := back
		back = false
		if PlanGalopStateIsStop[s] {
			// The end of a rule function checks for an error.
			if s, root = r.leave(); root >= 0 {
				return root
			}
			continue
		}
		if d := int(PlanGalopStateDecision[s]); d >= 0 {
			// ANTLR matches the alternatives of a set decision as one set.
			if after := PlanGalopDecisionSetAfter[d]; after >= 0 {
				r.state = s
				if e.ll1Alt(d) > 0 {
					r.reportMatch()
					r.take(false)
				} else {
					r.recoverInline(s, after, false)
				}
				s = after
				continue
			}
			alt, ok := r.decide(d, s, fromBack)
			if !ok {
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
			if k := PlanGalopOuterAltStart[d]; k >= 0 {
				r.enterOuterAlt(PlanGalopOuterAlt[int(k)+alt-1])
			}
			back = PlanGalopDecisionKind[d] == PlanGalopDecisionPlus && alt == int(PlanGalopDecisionLoopAlt[d])
			s = PlanGalopTransTarget[PlanGalopTransStart[s]+int32(alt)-1]
			continue
		}
		// The generated code checks for an error after these Syncs.
		checked := false
		switch PlanGalopStateSync[s] {
		case PlanGalopSyncLoopBack:
			r.state = s
			r.sync(s, false)
			back, checked = true, true
		case PlanGalopSyncBlockStart:
			if !fromBack {
				r.state = s
				r.sync(s, true)
				checked = true
			}
		}
		if checked && e.pending != nil {
			if s, root = r.leave(); root >= 0 {
				return root
			}
			continue
		}
		// An alternative of a left-recursive rule starts by changing the
		// rule's context.
		if len(PlanGalopStateContext) > 0 {
			if c, ok := PlanGalopStateContext[s]; ok {
				r.contextStep(c)
			}
		}
		i := PlanGalopTransStart[s]
		t := PlanGalopTransTarget[i]
		switch PlanGalopTransKind[i] {
		case PlanGalopKindEpsilon:
		case PlanGalopKindRule:
			r.state = s
			p.stack = append(p.stack, PlanGalopTransArg[i])
			if PlanGalopMaxPrec > 0 {
				e.precs = append(e.precs, PlanGalopStateCallPrec[s])
			}
			r.enter(PlanGalopStateRule[t], s)
		case PlanGalopKindPrec:
			// The generated code checks precpred and goes to its error exit.
			if level := PlanGalopTransArg[i]; level < e.prec() {
				r.state = s
				r.pend(e.failedPredicate(s, level))
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
		case PlanGalopKindAtom:
			r.state = s
			r.matchToken(s, t, p.la(1) == PlanGalopTransArg[i], true)
			// The generated code checks for an error after a token match.
			if e.pending != nil {
				if s, root = r.leave(); root >= 0 {
					return root
				}
				continue
			}
		default:
			r.state = s
			if PlanGalopStateWildcard[s] {
				r.matchToken(s, t, p.la(1) != antlr.TokenEOF, false)
			} else {
				r.matchSet(s, i, t)
			}
		}
		s = t
	}
}

// decide makes decision d at state s as ANTLR's generated code does (see
// PlanGalopEmu.decide), and reports false where that code goes to its error exit.
func (r *PlanGalopRecovery) decide(d int, s int32, fromBack bool) (int, bool) {
	e := &r.e
	pos := e.p.pos
	kind := PlanGalopDecisionKind[d]
	// A star loop's next iteration decides at its loop back's state.
	if !(kind == PlanGalopDecisionStar && fromBack) {
		r.state = s
	}
	ll1 := PlanGalopDecisionLL1[d]
	// A token an alternative accepts passes Sync too.
	if ll1 && e.pending == nil {
		if alt := e.ll1Alt(d); alt > 0 {
			return alt, true
		}
	}
	switch kind {
	case PlanGalopDecisionAlt:
		r.sync(s, true)
		if e.pending != nil {
			return 0, false
		}
	case PlanGalopDecisionOpt:
		// Adaptive prediction follows Sync with no error check.
		r.sync(s, true)
		if ll1 && e.pending != nil {
			return 0, false
		}
	case PlanGalopDecisionStar:
		if !fromBack {
			r.sync(s, true)
			if e.pending != nil {
				return 0, false
			}
		}
	case PlanGalopDecisionPlus:
		r.sync(s, false)
		if ll1 && e.pending != nil {
			return 0, false
		}
	}
	if !ll1 {
		alt, err := e.predict(d)
		if err != nil {
			r.pend(err)
			return 0, false
		}
		return alt, true
	}
	if alt := e.ll1Alt(d); alt > 0 {
		return alt, true
	}
	// An LL(1) choice fails; an optional block or a loop exits.
	if kind == PlanGalopDecisionAlt {
		r.pend(e.noViable(pos, pos))
		return 0, false
	}
	return int(PlanGalopAltLookStart[d+1] - PlanGalopAltLookStart[d]), true
}

// read is the furthest token ANTLR's parse has read so far: the current one
// (consuming a token reads the next) or one prediction or single-token
// deletion looked ahead to.
func (r *PlanGalopRecovery) read() int {
	p := r.e.p
	return min(max(p.pos, p.peek), len(p.types)-1)
}

// reportMatch is ANTLR's ReportMatch: a token matched, so error recovery ends.
func (r *PlanGalopRecovery) reportMatch() {
	r.recovering = false
	r.lastIndex = -1
	r.lastStates = r.lastStates[:0]
}

// recoverInline is ANTLR's RecoverInline at match state s, whose transition
// leads to next (see PlanGalopEmu.inlineFix). It returns the token single-token
// deletion consumes (the one after the current), or what single-token
// insertion returns (see missing), or -1 for a mismatch, which it leaves
// pending.
func (r *PlanGalopRecovery) recoverInline(s, next int32, add bool) int32 {
	switch fix, exp, err := r.e.inlineFix(s, next); fix {
	case PlanGalopFixDelete:
		r.deleteOne(err)
		return r.take(false)
	case PlanGalopFixInsert:
		r.report(err)
		return r.missing(exp, add)
	default:
		r.pend(err)
	}
	return -1
}

// deleteOne is ANTLR's single-token deletion: the current token is reported
// with err and skipped as an error token.
func (r *PlanGalopRecovery) deleteOne(err *PlanGalopEmuError) {
	r.report(err)
	r.take(true)
	r.reportMatch()
}

// matchToken is ANTLR's Match (match set) or MatchWildcard at state s, whose
// transition leads to next, where ok says the current token matches. Match
// returns nil, adding no conjured token, while an error is pending, as after
// a failed set match; MatchWildcard does not check.
func (r *PlanGalopRecovery) matchToken(s, next int32, ok, match bool) {
	if ok {
		r.reportMatch()
		r.label(s, r.take(false))
		return
	}
	if match && r.e.pending != nil {
		r.recoverInline(s, next, false)
		r.label(s, -1)
		return
	}
	r.label(s, r.recoverInline(s, next, true))
}

// matchSet is the generated code's match of the set at state s, whose
// transition i leads to next. Its label gets the current token, or what
// RecoverInline returns, and a list label appends that once (ANTLR assigns
// an implicit label first and appends its final value); a conjured token is
// not added to the tree.
func (r *PlanGalopRecovery) matchSet(s, i, next int32) {
	tok := int32(r.e.p.pos)
	if PlanGalopMatches(i, r.e.p.la(1)) {
		r.reportMatch()
		r.take(false)
	} else {
		tok = r.recoverInline(s, next, false)
	}
	r.label(s, tok)
}

// types are the types in x, ascending, EOF first.
func (x *PlanGalopExpected) types() []int32 {
	var out []int32
	for i, ok := range x.in {
		if ok {
			out = append(out, int32(i-1))
		}
	}
	return out
}

// first is ANTLR's IntervalSet.first(): the smallest type in x, EOF first,
// or 0 for an empty set.
func (x *PlanGalopExpected) first() int32 {
	for i, ok := range x.in {
		if ok {
			return int32(i - 1)
		}
	}
	return 0
}

// sync is ANTLR's Sync at state s, a block start or a loop back. It does
// nothing in error recovery mode or where the current token can follow s.
// At a block start it deletes one token when the token after it can follow,
// and otherwise leaves a mismatch pending; at a loop back it reports the
// token and skips to what can follow s or a rule being parsed.
func (r *PlanGalopRecovery) sync(s int32, blockStart bool) {
	if r.recovering {
		return
	}
	switch fix, exp, err := r.e.syncFix(s, blockStart); fix {
	case PlanGalopFixSkip:
		r.report(err)
		r.recoverySet(exp)
		r.consumeUntil(exp)
	case PlanGalopFixDelete:
		r.deleteOne(err)
	case PlanGalopFixMismatch:
		r.pend(err)
	}
}

// leave ends the rule being parsed as the end of its generated function
// does: a pending error is reported and recovered from (errorExit), and the
// rule returns (see exit).
func (r *PlanGalopRecovery) leave() (int32, int32) {
	if r.e.pending != nil {
		r.errorExit()
	}
	follow, root := r.exit()
	if PlanGalopMaxPrec > 0 {
		r.e.precs = r.e.precs[:len(r.e.p.stack)]
	}
	return follow, root
}

// contextStep is what an alternative of a left-recursive rule does to the
// rule's context at its start (PlanGalopStateContext's encoding): an op
// alternative's PushNewRecursionContext, or a labeled primary one's new
// context, which keeps none of the children the rule had, as enterOuterAlt.
func (r *PlanGalopRecovery) contextStep(c uint32) {
	alt := uint8(c & PlanGalopContextAlt)
	if c&PlanGalopContextPush == 0 {
		r.enterOuterAlt(alt)
		return
	}
	r.recursionStart(alt, uint16(c>>PlanGalopContextLeftShift))
}

// errorExit reports the pending error and recovers as ANTLR's Recover does:
// a second error at the same token and state first skips that token, then
// the input is skipped to a token that can follow a rule being parsed.
func (r *PlanGalopRecovery) errorExit() {
	e := &r.e
	p := e.p
	r.reportPending(e.pending)
	e.pending = nil
	if r.lastIndex == p.pos && slices.Contains(r.lastStates, r.state) {
		r.take(r.recovering)
	}
	r.lastIndex = p.pos
	r.lastStates = append(r.lastStates, r.state)
	set := PlanGalopNewExpected()
	r.recoverySet(set)
	r.consumeUntil(set)
}

// recoverySet adds ANTLR's error recovery set to x: what can follow each
// rule being parsed but the entry rule.
func (r *PlanGalopRecovery) recoverySet(x *PlanGalopExpected) {
	for _, f := range r.e.p.stack {
		x.add(PlanGalopTokenSets[PlanGalopStateNext[f]])
	}
}

// consumeUntil skips tokens until one in set, or EOF.
func (r *PlanGalopRecovery) consumeUntil(set *PlanGalopExpected) {
	p := r.e.p
	for t := p.la(1); t != antlr.TokenEOF && !set.has(t); t = p.la(1) {
		r.take(r.recovering)
	}
}

// newContext makes the context of rule (its index), as ANTLR's generated
// rule function does.
func (p *PlanGalopParser) newContext(rule int32, parent antlr.ParserRuleContext, invoking int) antlr.ParserRuleContext {
	switch rule {
	case 0:
		return NewExprContext(p.PlanParser, parent, invoking)
	case 1:
		return NewFieldNameContext(p.PlanParser, parent, invoking)
	case 2:
		return NewFieldReferenceContext(p.PlanParser, parent, invoking)
	case 3:
		return NewTextMatchOptionContext(p.PlanParser, parent, invoking)
	}
	panic("no rule with this index")
}

