// setLabel stores tok, or child's context, in ctx's field of label (the
// encoding of PlanGalopStateLabel), as ANTLR's generated code does.
func (p *PlanGalopParser) setLabel(ctx antlr.ParserRuleContext, label uint16, tok antlr.Token, child antlr.ParserRuleContext) {
	switch c := ctx.(type) {
	case *TimestamptzCompareForwardContext:
		switch label {
		case 1:
			c.op1 = tok
		case 2:
			c.interval_string = tok
		case 3:
			c.op2 = tok
		case 4:
			c.compare_string = tok
		}
	case *TimestamptzCompareReverseContext:
		switch label {
		case 4:
			c.compare_string = tok
		case 3:
			c.op2 = tok
		case 1:
			c.op1 = tok
		case 2:
			c.interval_string = tok
		}
	case *MatchSimpleContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *MatchThresholdContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *UnaryContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *MulDivModContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *AddSubContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *ShiftContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *TermContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *SpatialBinaryContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *MembershipMatchWithOptionContext:
		switch label {
		case 6:
			c.function = tok
		case 7:
			c.field = child.(IFieldReferenceContext)
		case 8:
			c.option = tok
		case 9:
			c.kind = tok
		}
	case *RangeContext:
		switch label {
		case 1:
			c.op1 = tok
		case 3:
			c.op2 = tok
		}
	case *ReverseRangeContext:
		switch label {
		case 1:
			c.op1 = tok
		case 3:
			c.op2 = tok
		}
	case *RelationalContext:
		switch label {
		case 5:
			c.op = tok
		}
	case *EqualityContext:
		switch label {
		case 5:
			c.op = tok
		}
	}
}
